-- بيانات مقرر فيزياء 1 (المقرر 101، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L2-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يسير متسابق بسرعة مقدارها 12 m/s في منعطف دائري قطره 60 m. ما مقدار تسارعه المركزي؟', null, null, '["2.4 m/s²","4.8 m/s²","0.40 m/s²","0.20 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 170، 171 — المثال 2، المسائل التدريبية'),
('mcq', 2, 'كرة كتلتها 0.25 kg تتحرك في دائرة أفقية نصف قطرها 0.60 m بسرعة مقدارها 3.0 m/s. ما مقدار القوة المركزية المؤثرة فيها؟', null, null, '["1.3 N","1.4 N","15 N","3.8 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 171 — المراجعة 15 و17'),
('mcq', 3, 'يدوّر لاعب كرة كتلتها 4.0 kg مربوطة في سلسلة، فتتحرك في دائرة أفقية نصف قطرها 1.5 m كما في الشكل، وتُتم دورة واحدة في 1.2 s. ما مقدار القوة المركزية المؤثرة في الكرة؟', null, '[{"src":"qimg/phys1/c6l2-o09-hammer.svg","alt":"دائرة خضراء فاتحة محاطة بخط متقطع تمثل مسار الكرة، وفي مركزها دائرة صغيرة بيضاء تمثل اللاعب. خط من المركز إلى كرة رمادية على الدائرة في أعلى يمينها، مكتوب عنده 1.5 m. وسهم رمادي منحنٍ خارج الدائرة يبين اتجاه الدوران."}]'::jsonb, '["$1.6\\times10^{2}\\ \\text{N}$","$2.0\\times10^{2}\\ \\text{N}$","$26\\ \\text{N}$","$21\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب بدلالة الزمن الدوري', 'متوسط', 'الكتاب ص 181 — التقويم 43'),
('mcq', 4, 'يبيّن الشكل جسمًا كتلته 0.50 kg يتحرك حركة دائرية منتظمة على دائرة نصف قطرها 1.2 m، والقوة المركزية المؤثرة فيه 6.0 N. ما مقدار سرعته المماسية؟', null, '[{"src":"qimg/phys1/c6l2-o09-force.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ يبين الدوران عكس عقارب الساعة. جسم عند أقصى يمين الدائرة مكتوب بجانبه 0.50 kg، وخط أخضر متقطع من المركز إليه مكتوب تحته 1.2 m. ويخرج من الجسم سهم أزرق أفقي نحو المركز مكتوب فوقه 6.0 N."}]'::jsonb, '["14 m/s","3.2 m/s","3.8 m/s","1.6 m/s"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'متوسط', 'الكتاب ص 183 — اختبار مقنن 3'),
('mcq', 5, 'سيارة تسلك منعطفًا أفقيًا مستويًا نصف قطره 45.0 m، ومعامل الاحتكاك السكوني بين عجلاتها والطريق 0.50. ما أقصى مقدار سرعة يمكن أن تسلك به المنعطف دون أن تنزلق؟', null, null, '["$2.2\\times10^{2}\\ \\text{m/s}$","$21\\ \\text{m/s}$","$15\\ \\text{m/s}$","$11\\ \\text{m/s}$"]'::jsonb, 'تحليل', 'حساب مع الاحتكاك', 'صعب', 'الكتاب ص 171، 181 — المسألة 11، التقويم 44'),
('mcq', 6, 'طائرة تدور في مسار دائري أفقي بسرعة مقدارها 150 m/s. ما أقل نصف قطر للمسار يُبقي تسارعها المركزي لا يزيد على 6.0 m/s²؟', null, null, '["$3.8\\ \\text{km}$","$25\\ \\text{m}$","$1.4\\times10^{2}\\ \\text{km}$","$0.38\\ \\text{km}$"]'::jsonb, 'تحليل', 'حساب مع تحويل وحدات', 'صعب', 'الكتاب ص 171 — المسألة 12'),
('mcq', 7, 'سدادة مطاطية تدور في دائرة أفقية مربوطة بخيط، وبياناتها مبيّنة في الشكل. ما مقدار قوة الشد في الخيط (أهمل وزن السدادة)؟', null, '[{"src":"qimg/phys1/c6l2-o09-stopper.svg","alt":"دائرة يدور عليها جسم صغير مستطيل عند أقصى يمينها، مكتوب بجانبه m = 20 g. خط أخضر من المركز إلى الجسم مكتوب فوقه r = 0.75 m. سهم رمادي منحنٍ يبين اتجاه الدوران، ومكتوب أسفل الدائرة T = 1.5 s (الزمن الدوري)."}]'::jsonb, '["$2.6\\times10^{2}\\ \\text{N}$","$0.39\\ \\text{N}$","$0.042\\ \\text{N}$","$0.26\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 170 — المثال 2'),
('essay', 1, 'تكمل سيارة سباق كتلتها 720 kg دورة كاملة في مضمار دائري نصف قطره 60.0 m في 18.0 s، بسرعة ثابتة المقدار. (a) ما مقدار تسارعها المركزي؟ (b) ما مقدار القوة التي يؤثر بها الطريق في عجلاتها لإنتاج هذا التسارع، وما نوعها؟', null, null, null, 'تطبيق', 'مسألة', 'متوسط', 'الكتاب ص 181 — التقويم 42'),
('essay', 2, 'سيارة كتلتها 1200 kg تسلك منعطفًا أفقيًا مستويًا نصف قطره 50.0 m بسرعة 15 m/s. (a) احسب القوة المركزية اللازمة. (b) ما أقل معامل احتكاك سكوني يمنع انزلاقها؟ (c) إذا كان معامل الاحتكاك السكوني للطريق المبتل 0.40 فقط، هل تنزلق السيارة بهذه السرعة؟ علّل بحساب أقصى سرعة آمنة.', null, null, null, 'تحليل', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 171، 181 — المسألة 11، التقويم 44'),
('essay', 3, 'يحرك لاعب سلسلة مهملة الكتلة طولها 90.0 cm، في نهايتها كرة كتلتها 4.0 kg، في مسار دائري أفقي فوق رأسه. إذا أكملت الكرة دورة كاملة في 1.5 s، فاحسب: (a) مقدار سرعة الكرة. (b) قوة الشد في السلسلة (اعدّ السلسلة أفقية تقريبًا).', null, null, null, 'تطبيق', 'مسألة', 'سهل', 'الكتاب ص 183 — اختبار مقنن 9')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, '$r = \frac{60}{2} = 30\ \text{m}$؛ $a_{\text{C}} = \frac{v^2}{r} = \frac{(12\ \text{m/s})^2}{30\ \text{m}} = 4.8\ \text{m/s}^2$.', '["استُعمل القطر 60 m بدل نصف القطر 30 m.","","لم تُربَّع السرعة: $\\frac{12}{30}$.","لم تُربَّع السرعة واستُعمل القطر بدل نصف القطر معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.254Z"}'::jsonb),
('mcq', 2, 3, '$F_{\text{المحصلة}} = \frac{mv^2}{r} = \frac{(0.25\ \text{kg})(3.0\ \text{m/s})^2}{0.60\ \text{m}} = 3.8\ \text{N}$.', '["لم تُربَّع السرعة: $\\frac{(0.25)(3.0)}{0.60}$.","ضُرب في نصف القطر بدل القسمة عليه: $(0.25)(3.0)^2(0.60)$.","هذا التسارع المركزي $\\frac{v^2}{r}$ دون الضرب في الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-21T13:36:33.255Z"}'::jsonb),
('mcq', 3, 0, '$a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2} = \frac{4\pi^2 (1.5)}{(1.2)^2} = 41\ \text{m/s}^2$؛ $F = ma_{\text{C}} = (4.0)(41.1) = 1.6\times10^{2}\ \text{N}$.', '["","قُسم على $\\text{T}$ بدل $\\text{T}^2$.","استُعمل $\\frac{2\\pi r}{\\text{T}^2}$ بدل $\\frac{4\\pi^2 r}{\\text{T}^2}$.","حُسبت السرعة صحيحة لكن استُعمل $\\frac{mv}{r}$ دون تربيع السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-21T13:36:33.255Z"}'::jsonb),
('mcq', 4, 2, '$F = \frac{mv^2}{r} \Rightarrow v = \sqrt{\frac{Fr}{m}} = \sqrt{\frac{(6.0)(1.2)}{0.50}} = 3.8\ \text{m/s}$.', '["هذا $v^2$؛ لم يُؤخذ الجذر التربيعي.","قُسمت القوة على حاصل ضرب الكتلة في نصف القطر: $\\sqrt{\\frac{F}{mr}}$.","","ضُربت القوة في الكتلة بدل القسمة عليها: $\\sqrt{\\frac{Fm}{r}}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.255Z"}'::jsonb),
('mcq', 5, 2, 'القوة المركزية هي الاحتكاك السكوني وأقصاه $\mu_s F_{\text{N}} = \mu_s mg$؛ $\frac{mv^2}{r} = \mu_s mg \Rightarrow v = \sqrt{\mu_s g r} = \sqrt{(0.50)(9.80)(45.0)} = 14.8 \approx 15\ \text{m/s}$ (رقمان معنويان لأن $\mu_s = 0.50$).', '["هذا $v^2 = \\mu_s g r$؛ لم يُؤخذ الجذر التربيعي.","أُهمل معامل الاحتكاك: $\\sqrt{gr}$.","","وُضع معامل الاحتكاك خارج الجذر: $\\mu_s\\sqrt{gr}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.256Z"}'::jsonb),
('mcq', 6, 0, '$r = \frac{v^2}{a_{\text{C}}} = \frac{(150\ \text{m/s})^2}{6.0\ \text{m/s}^2} = 3.75\times10^{3}\ \text{m} \approx 3.8\ \text{km}$؛ وأي نصف قطر أصغر يجعل التسارع أكبر من 6.0 m/s².', '["","قُسمت السرعة على التسارع دون تربيعها: $\\frac{v}{a_{\\text{C}}}$.","ضُرب مربع السرعة في التسارع بدل القسمة عليه.","خطأ في تحويل 3750 m إلى km (القسمة على $10^4$ بدل $10^3$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.256Z"}'::jsonb),
('mcq', 7, 3, '$m = 20\ \text{g} = 0.020\ \text{kg}$؛ $a_{\text{C}} = \frac{4\pi^2 (0.75)}{(1.5)^2} = 13\ \text{m/s}^2$؛ $F_{\text{T}} = ma_{\text{C}} = (0.020)(13.2) = 0.26\ \text{N}$.', '["لم تُحوَّل الكتلة من g إلى kg.","قُسم على $\\text{T}$ بدل $\\text{T}^2$.","استُعمل $\\frac{2\\pi r}{\\text{T}^2}$ للتسارع بدل $\\frac{4\\pi^2 r}{\\text{T}^2}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.257Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2} = \frac{4\pi^2 (60.0\ \text{m})}{(18.0\ \text{s})^2} = 7.31\ \text{m/s}^2$ نحو المركز. (b) $F_{\text{المحصلة}} = ma_{\text{C}} = (720\ \text{kg})(7.31\ \text{m/s}^2) = 5.26\times10^{3}\ \text{N}$ نحو مركز المضمار، وهي قوة الاحتكاك السكوني بين العجلات والطريق.', '["$a_{\\text{C}} = 7.31\\ \\text{m/s}^2$","$F = 5.26\\times10^{3}\\ \\text{N}$","الاتجاه نحو المركز","نوع القوة: احتكاك سكوني"]'::jsonb, '["$a_{\\text{C}} = \\frac{4\\pi^2 \\times 60.0}{18.0^2} = 7.31\\ \\text{m/s}^2$","$F = 720 \\times 7.31 = 5.26\\times10^{3}\\ \\text{N}$"]'::jsonb, '[{"element":"التسارع","marks":1},{"element":"القوة","marks":1},{"element":"الاتجاه والنوع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حسابان صحيحان مع الاتجاه والنوع"},{"level":"درجتان","description":"حسابان صحيحان دون النوع أو خطأ في حساب واحد"},{"level":"درجة واحدة","description":"حساب التسارع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على T بدل T²","إهمال تحديد مصدر القوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.257Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $F = \frac{mv^2}{r} = \frac{(1200)(15)^2}{50.0} = 5.4\times10^{3}\ \text{N}$. (b) الاحتكاك السكوني هو القوة المركزية: $\mu_s mg \ge \frac{mv^2}{r}$، $\mu_s = \frac{v^2}{gr} = \frac{(15)^2}{(9.80)(50.0)} = 0.46$. (c) $v_{\text{max}} = \sqrt{\mu_s g r} = \sqrt{(0.40)(9.80)(50.0)} = 14\ \text{m/s}$؛ وهي أقل من 15 m/s، فأقصى احتكاك متاح لا يكفي، فتنزلق السيارة (في اتجاه المماس للمنعطف).', '["$F = 5.4\\times10^{3}\\ \\text{N}$","$\\mu_s = 0.46$","$v_{\\text{max}} = 14\\ \\text{m/s}$","الحكم: تنزلق"]'::jsonb, '["$F = 1200 \\times 225 / 50.0 = 5.4\\times10^{3}\\ \\text{N}$","$F_{\\text{N}} = mg$، و$\\mu_s mg = \\frac{mv^2}{r}$","$\\mu_s = \\frac{225}{9.80 \\times 50.0} = 0.46$","$v_{\\text{max}} = \\sqrt{0.40 \\times 9.80 \\times 50.0} = 14\\ \\text{m/s}$"]'::jsonb, '[{"element":"القوة","marks":1},{"element":"معامل الاحتكاك","marks":1},{"element":"أقصى سرعة","marks":1},{"element":"الحكم مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة مع حكم معلل"},{"level":"2–3 درجات","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان الجذر في حساب أقصى سرعة","استعمال الوزن قوةً مركزية","الحكم دون مقارنة عددية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.258Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $r = 0.900\ \text{m}$؛ $v = \frac{2\pi r}{\text{T}} = \frac{2\pi (0.900\ \text{m})}{1.5\ \text{s}} = 3.8\ \text{m/s}$. (b) $F_{\text{T}} = ma_{\text{C}} = \frac{m4\pi^2 r}{\text{T}^2} = \frac{(4.0)(4\pi^2)(0.900)}{(1.5)^2} = 63\ \text{N}$.', '["تحويل الطول إلى m","$v = 3.8\\ \\text{m/s}$","$F_{\\text{T}} = 63\\ \\text{N}$"]'::jsonb, '["$r = 90.0\\ \\text{cm} = 0.900\\ \\text{m}$","$v = \\frac{2\\pi \\times 0.900}{1.5} = 3.77 \\approx 3.8\\ \\text{m/s}$","$a_{\\text{C}} = \\frac{4\\pi^2 \\times 0.900}{1.5^2} = 15.8\\ \\text{m/s}^2$","$F_{\\text{T}} = 4.0 \\times 15.8 = 63\\ \\text{N}$"]'::jsonb, '[{"element":"التحويل","marks":1},{"element":"السرعة","marks":1},{"element":"قوة الشد","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حسابات صحيحة بأرقام معنوية مناسبة"},{"level":"درجتان","description":"خطأ واحد في التحويل أو الحساب"},{"level":"درجة واحدة","description":"كتابة العلاقات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل cm إلى m","القسمة على T بدل T² في حساب القوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.258Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O09') and x.type = v.type and x.number = v.number
