insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L2-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما مصدر القوة المركزية التي تُبقي الأرض في مدارها حول الشمس؟', null, null, '["قوة الطرد المركزي الناتجة عن دوران الأرض حول الشمس","قوة الاحتكاك بين الأرض والفضاء المحيط بها","قوة التجاذب الكتلي بين الشمس والأرض","قوة الشد في خيوط غير مرئية تربط الأرض بالشمس"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 169 — القوة المركزية (أمثلة)'),
('mcq', 2, 'في رياضة رمي المطرقة، ما مصدر القوة المركزية المؤثرة في المطرقة قبل إفلاتها؟', null, null, '["قوة الشد في السلسلة نحو الرامي","وزن المطرقة المؤثر فيها رأسيًا إلى أسفل","مقاومة الهواء المعاكسة لاتجاه حركة المطرقة","قوة دفع من يد الرامي في اتجاه سرعة المطرقة المماسية"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 169 — القوة المركزية (أمثلة)'),
('mcq', 3, 'يبيّن الشكل مخطط الجسم الحر لسيارة تسلك منعطفًا أفقيًا مستويًا (منظورًا إليها من الخلف). ما مصدر القوة المركزية المؤثرة في السيارة؟', null, '[{"src":"qimg/phys1/c6l2-o10-car.svg","alt":"سيارة مرسومة من الخلف على شكل مستطيل بحواف دائرية فوق عجلتين على أرض أفقية. من نقطة في منتصفها تخرج ثلاثة أسهم زرقاء: إلى أعلى مكتوب عنده FN، وإلى أسفل مساوٍ له مكتوب عنده Fg، وأفقي إلى اليسار أقصر منهما مكتوب عنده ff. وأسفل الشكل سهم رمادي إلى اليسار مكتوب بجانبه «نحو مركز المنعطف»."}]'::jsonb, '["الوزن الذي تؤثر به الأرض في السيارة إلى أسفل","القوة العمودية التي يؤثر بها الطريق في السيارة","قوة المحرك التي تدفع السيارة في اتجاه حركتها","قوة الاحتكاك السكوني بين العجلات والطريق"]'::jsonb, 'تذكر', 'تحديد مصدر قوة', 'متوسط', 'الكتاب ص 171 — المسائل 10 و11'),
('mcq', 4, 'في أثناء دوران حوض الغسالة لتجفيف الملابس، ما القوة التي تجعل الملابس تتحرك في مسار دائري؟', null, null, '["قوة الطرد المركزي التي تدفع الملابس نحو جدار الحوض","قوة يؤثر بها جدار الحوض في الملابس نحو المركز","وزن الملابس المؤثر فيها رأسيًا إلى أسفل في الحوض","قوة الشد في خيوط نسيج الملابس المبللة بالماء"]'::jsonb, 'فهم', 'تحديد مصدر قوة', 'متوسط', 'الكتاب ص 171 — المراجعة 13'),
('mcq', 5, 'في لعبة الأسطوانة الدوّارة يقف شخص مستندًا إلى جدارها الداخلي، فتؤثر فيه القوى المبيّنة في الشكل. أيّ هذه القوى هي القوة المركزية؟', null, '[{"src":"qimg/phys1/c6l2-o10-rotor.svg","alt":"جداران رأسيان متقابلان يمثلان مقطعًا لأسطوانة دوّارة، وبينهما خط رأسي متقطع مكتوب عنده «محور الدوران». شخص ممثل بنقطة ملاصقة للجدار الأيسر، وتخرج منه ثلاثة أسهم زرقاء: أفقي إلى اليمين نحو المحور مكتوب عنده FN، ورأسي إلى أعلى مكتوب عنده ff، ورأسي إلى أسفل مساوٍ له مكتوب عنده Fg."}]'::jsonb, '["القوة العمودية من الجدار نحو محور الدوران","قوة الاحتكاك بين الجدار والشخص إلى أعلى","قوة الجاذبية الأرضية المؤثرة في الشخص إلى أسفل","قوة الطرد المركزي التي تضغط الشخص على الجدار"]'::jsonb, 'تحليل', 'تحليل مخطط', 'صعب', 'الكتاب ص 178 — محطات الفضاء الدوارة (الأسطوانة الدوارة)'),
('mcq', 6, 'أنت تتحرك حركة دائرية منتظمة بسبب دوران الأرض اليومي. ما الذي يُكسبك التسارع المركزي نحو محور الأرض وأنت واقف عند خط الاستواء؟', null, null, '["القوة العمودية من سطح الأرض، إذ تزيد قليلًا على وزنك","قوة الطرد المركزي الناتجة عن دوران الأرض حول محورها","قوة الاحتكاك بين قدميك وسطح الأرض","جاذبية الأرض لك، إذ تزيد قليلًا على القوة العمودية"]'::jsonb, 'تحليل', 'تحديد مصدر قوة', 'صعب', 'الكتاب ص 171 — المراجعة 18'),
('mcq', 7, 'سدادة مطاطية مربوطة بخيط تدور في دائرة أفقية على سطح طاولة أفقية أملس. ما مصدر القوة المركزية المؤثرة فيها؟', null, null, '["القوة العمودية من سطح الطاولة","قوة الشد في الخيط","وزن السدادة المؤثر فيها","الاحتكاك بين السدادة والطاولة"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 170 — المثال 2'),
('essay', 1, 'اذكر ثلاثة أمثلة من الحياة لأجسام تتحرك في مسارات دائرية، وحدد في كل مثال مصدر القوة المركزية المسببة للتسارع المركزي واتجاهها.', null, null, null, 'تذكر', 'ذكر أمثلة', 'متوسط', 'الكتاب ص 169، 171 — القوة المركزية، المراجعة 13'),
('essay', 2, 'عدّاء يركض بسرعة ثابتة المقدار 7.5 m/s في منعطف دائري نصف قطره 20 m. (a) احسب مقدار تسارعه المركزي. (b) ما مصدر القوة المؤثرة فيه نحو المركز؟ (c) لماذا يصعب عليه أن يسلك المنعطف بالسرعة نفسها إذا كان المضمار مبتلًا وزلقًا؟', null, null, null, 'تطبيق', 'حساب وتحديد مصدر', 'متوسط', 'الكتاب ص 171 — المسألة 10'),
('essay', 3, 'إنك تتحرك حركة دائرية منتظمة بسبب دوران الأرض اليومي. (a) ما المصدر الذي يولّد القوة التي تؤدي إلى تسارعك المركزي؟ (b) كيف تؤثر هذه الحركة في وزنك الظاهري عند خط الاستواء؟ (c) إذا علمت أن التسارع المركزي عند خط الاستواء $3.37\times10^{-2}\ \text{m/s}^2$، فاحسب الفرق بين وزنك الحقيقي ووزنك الظاهري إذا كانت كتلتك 60.0 kg.', null, null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 171 — المراجعة 18')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
