select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'القوة المسببة لدوران الأرض حول الشمس هي قوة جذب مركزية ناتجة عن قوة التجاذب الكتلي بين الشمس والأرض.', '["قوة الطرد المركزي وهمية، ولو وُجدت لكانت إلى الخارج لا نحو الشمس.","لا يوجد احتكاك يُذكر في الفضاء، والاحتكاك لا يتجه نحو الشمس.","","لا يوجد حبل أو خيط بين الأرض والشمس؛ فالقوة تؤثر عن بُعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.259Z"}'::jsonb),
('mcq', 2, 0, 'القوة المسببة لدوران المطرقة في مسار دائري ناتجة عن قوة الشد في السلسلة في اتجاه المركز.', '["","الوزن رأسي، والقوة المركزية في هذه الحركة أفقية نحو الرامي.","مقاومة الهواء تعاكس السرعة (مماسية)، فلا تتجه نحو المركز.","قوة في اتجاه السرعة تزيد مقدارها ولا تغير اتجاهها، فليست مركزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.259Z"}'::jsonb),
('mcq', 3, 3, 'القوة الوحيدة الأفقية المتجهة نحو مركز المنعطف هي قوة الاحتكاك السكوني $\boldsymbol{f}_{f}$ التي يؤثر بها الطريق في العجلات؛ أما $\boldsymbol{F}_g$ و$\boldsymbol{F}_{\text{N}}$ فرأسيتان متوازنتان.', '["الوزن رأسي إلى أسفل ولا مركّبة له نحو مركز المنعطف الأفقي.","القوة العمودية رأسية إلى أعلى على الطريق المستوي، فلا تتجه نحو المركز.","قوة في اتجاه الحركة لا تغير اتجاه السرعة؛ والقوة المركزية عمودية على السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.260Z"}'::jsonb),
('mcq', 4, 1, 'جدار الحوض يدفع الملابس نحو محور الدوران (قوة عمودية من الجدار)، وهذه القوة هي القوة المركزية التي تُبقي الملابس في مسار دائري.', '["قوة الطرد المركزي وهمية؛ والملابس تضغط على الجدار بسبب قصورها الذاتي.","","الوزن رأسي، والحركة الدائرية أفقية حول محور الحوض.","شد خيوط النسيج قوى داخلية لا تجعل الملابس كلها تدور حول المحور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-21T13:36:33.260Z"}'::jsonb),
('mcq', 5, 0, 'المحور رأسي، فاتجاه المركز أفقي نحو المحور. القوة الوحيدة في هذا الاتجاه هي القوة العمودية $\boldsymbol{F}_{\text{N}}$ التي يؤثر بها الجدار في الشخص، فهي القوة المركزية؛ أما الاحتكاك فيوازن الوزن رأسيًا.', '["","الاحتكاك هنا رأسي يوازن الوزن فيمنع الانزلاق، ولا يتجه نحو المحور.","الوزن رأسي ولا مركّبة له نحو محور الدوران الرأسي.","هذه قوة وهمية لا تظهر في مخطط الجسم الحر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.260Z"}'::jsonb),
('mcq', 6, 3, 'عند خط الاستواء يتجه المركز رأسيًا إلى أسفل. القوة المركزية هي محصلة قوة الجاذبية (إلى أسفل) والقوة العمودية (إلى أعلى): $F_g - F_{\text{N}} = ma_{\text{C}}$، فتكون قوة الجاذبية أكبر قليلًا من القوة العمودية، وهي مصدر القوة المركزية.', '["لو زادت القوة العمودية على الوزن لكانت المحصلة إلى أعلى بعيدًا عن المركز.","قوة الطرد المركزي وهمية ولا يمكن أن تكون مصدرًا لقوة نحو المركز.","الاحتكاك يوازي السطح، والمطلوب قوة رأسية نحو مركز الأرض عند خط الاستواء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-21T13:36:33.261Z"}'::jsonb),
('mcq', 7, 1, 'الخيط يسحب السدادة نحو مركز الدائرة؛ فقوة الشد هي القوة الأفقية الوحيدة وهي القوة المركزية.', '["القوة العمودية رأسية توازن الوزن، والقوة المركزية أفقية.","","الوزن رأسي إلى أسفل، فلا يتجه نحو مركز الدائرة الأفقية.","السطح أملس فلا احتكاك، والاحتكاك الحركي يعاكس السرعة لا يتجه نحو المركز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.261Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أمثلة مقبولة: (1) دوران الأرض حول الشمس: المصدر قوة التجاذب الكتلي بين الشمس والأرض، نحو الشمس. (2) دوران المطرقة (أو حجر بخيط): المصدر قوة الشد في السلسلة (الخيط)، نحو يد الرامي. (3) سيارة أو عدّاء في منعطف أفقي: المصدر قوة الاحتكاك السكوني بين العجلات (الحذاء) والطريق، نحو مركز المنعطف. (4) ملابس في حوض الغسالة الدوّار: المصدر القوة التي يؤثر بها جدار الحوض، نحو المحور. وفي جميع الأمثلة تتجه القوة المركزية نحو مركز المسار الدائري.', '["مثال أول مع مصدره","مثال ثانٍ مع مصدره","مثال ثالث مع مصدره","الاتجاه نحو المركز"]'::jsonb, '[]'::jsonb, '[{"element":"المثال الأول ومصدره","marks":1},{"element":"المثال الثاني ومصدره","marks":1},{"element":"المثال الثالث ومصدره","marks":1},{"element":"تحديد الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاثة أمثلة صحيحة بمصادرها واتجاهها"},{"level":"2–3 درجات","description":"مثالان صحيحان أو ثلاثة دون الاتجاه"},{"level":"درجة واحدة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر قوة الطرد المركزي مصدرًا","عدّ الوزن مصدر القوة المركزية في المنعطف الأفقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.261Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $a_{\text{C}} = \frac{v^2}{r} = \frac{(7.5\ \text{m/s})^2}{20\ \text{m}} = 2.8\ \text{m/s}^2$ نحو مركز المنعطف. (b) المصدر قوة الاحتكاك السكوني التي تؤثر بها أرض المضمار في حذاء العدّاء نحو المركز. (c) المضمار المبتل معامل احتكاكه أصغر، فأقصى قوة احتكاك ممكنة أصغر، وقد لا تكفي لتوفير القوة المركزية $\frac{mv^2}{r}$ اللازمة، فينزلق العدّاء؛ لذا يلزمه خفض سرعته.', '["$a_{\\text{C}} = 2.8\\ \\text{m/s}^2$","المصدر: الاحتكاك السكوني","المضمار المبتل: احتكاك أقل لا يكفي للقوة المركزية"]'::jsonb, '["$a_{\\text{C}} = \\frac{7.5^2}{20} = 2.8\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الحساب","marks":1},{"element":"المصدر","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تربيع السرعة","عدّ القوة العمودية مصدر القوة المركزية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-21T13:36:33.262Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) المصدر جاذبية الأرض؛ فالقوة المركزية هي محصلة قوة الجاذبية إلى أسفل (نحو المركز) والقوة العمودية من الأرض إلى أعلى. (b) بتطبيق القانون الثاني على المحور المركزي: $F_g - F_{\text{N}} = ma_{\text{C}}$، فتكون $F_{\text{N}}$ (التي يقرؤها الميزان، أي الوزن الظاهري) أقل قليلًا من الوزن الحقيقي. (c) الفرق $= ma_{\text{C}} = (60.0\ \text{kg})(3.37\times10^{-2}\ \text{m/s}^2) = 2.02\ \text{N}$، وهو صغير جدًا مقارنة بالوزن $mg = 588\ \text{N}$.', '["المصدر: جاذبية الأرض (محصلتها مع القوة العمودية)","$F_g - F_{\\text{N}} = ma_{\\text{C}}$","الوزن الظاهري أقل قليلًا","الفرق 2.02 N"]'::jsonb, '["$F_g - F_{\\text{N}} = ma_{\\text{C}}$","$F_g - F_{\\text{N}} = 60.0 \\times 3.37\\times10^{-2} = 2.02\\ \\text{N}$"]'::jsonb, '[{"element":"المصدر","marks":1},{"element":"أثرها في الوزن الظاهري مع العلاقة","marks":1},{"element":"الحساب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوزن الظاهري يزداد","نسبة القوة المركزية إلى قوة طرد مركزي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-21T13:36:33.262Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
