from (values
('mcq', 1, 'عندما تنعطف سيارة فجأة نحو اليسار، يندفع الراكب الجالس بجانب السائق نحو الباب الأيمن. ما التفسير الصحيح لذلك؟', null, null, '["تؤثر في الراكب قوة طرد مركزي حقيقية تدفعه إلى خارج المنعطف","تؤثر في الراكب القوة المركزية فتدفعه إلى خارج المنعطف","يدفع الباب الأيمن الراكب إلى الخارج في اتجاه المنعطف","يستمر الراكب بقصوره الذاتي في خط مستقيم والسيارة تنعطف"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 171 — القوة الوهمية، الشكل 6-8'),
('mcq', 2, 'ما الوصف الصحيح لـ«قوة الطرد المركزي» التي يتحدث عنها بعض الناس عند الدوران في منعطف؟', null, null, '["قوة حقيقية تساوي القوة المركزية مقدارًا وتعاكسها اتجاهًا","قوة وهمية لا وجود لها؛ إذ لا يوجد جسم يؤثر بها","قوة حقيقية تؤثر بها الأرض في الأجسام الدوّارة إلى الخارج","قوة رد الفعل على وزن الجسم الدوّار على المنعطف"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 171 — القوة الوهمية، الشكل 6-8'),
('mcq', 3, 'سيارة تنعطف نحو اليسار كما في الشكل (منظورًا من أعلى). لو لم تؤثر السيارة في الراكب (النقطة) بأي قوة أفقية، فأيّ المسارات المرقمة يسلكه الراكب بالنسبة إلى الأرض؟', null, '[{"src":"qimg/phys1/c6l2-o11-car.svg","alt":"منظر من أعلى لطريق يتجه إلى أعلى ثم ينعطف إلى اليسار حول نقطة مكتوب عندها «مركز المنعطف» على اليسار. سيارة صفراء على الطريق قبل المنعطف مباشرة وفيها نقطة تمثل الراكب. من الراكب تخرج أسهم متقطعة مرقمة: المسار 1 مستقيم إلى أعلى (إلى الأمام)، والمسار 2 أفقي إلى اليمين، والمسار 4 أفقي إلى اليسار نحو مركز المنعطف، والمسار 3 هو منتصف الطريق المنحني الذي ينعطف إلى اليسار ومُعلّم برقم 3 عند نهايته."}]'::jsonb, '["المسار 2","المسار 3","المسار 1","المسار 4"]'::jsonb, 'فهم', 'تحديد مسار من شكل', 'متوسط', 'الكتاب ص 171 — القوة الوهمية، الشكل 6-8'),
('mcq', 4, 'ما القوة التي تجعل الراكب يتحرك مع السيارة في المنعطف؟', null, null, '["قوة الباب أو المقعد في الراكب نحو مركز المنعطف","قوة الطرد المركزي التي تدفع الراكب نحو باب السيارة","القوة التي يؤثر بها الراكب في الباب إلى خارج المنعطف","قوة محرك السيارة التي تدفع الراكب في اتجاه حركته"]'::jsonb, 'فهم', 'تحديد قوة', 'متوسط', 'الكتاب ص 171 — القوة الوهمية، الشكل 6-8'),
('mcq', 5, 'كتب طالب في تقريره: «يبقى القمر الصناعي في مداره الدائري حول الأرض لأن قوة جذب الأرض له تتوازن مع قوة الطرد المركزي المؤثرة فيه». ما التقويم الصحيح لعبارة الطالب؟', null, null, '["صحيحة؛ لأن تساوي القوتين يُبقي بُعد القمر عن الأرض ثابتًا","خاطئة؛ فقوة الطرد وهمية، وجذب الأرض هو المحصلة نحو المركز","صحيحة؛ لأن القوتين زوجا تأثير متبادل يؤثران في القمر نفسه","خاطئة؛ لأن قوة الطرد المركزي أكبر من قوة جذب الأرض للقمر"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 169، 171 — القوة المركزية، القوة الوهمية'),
('mcq', 6, 'شعرتَ في منعطف بأن «قوة» تدفعك إلى الخارج، فبحثت عن الجسم الذي يؤثر بها فيك فلم تجده. ماذا تستنتج؟', null, null, '["أنها قوة مجالية لا تحتاج إلى جسم يؤثر بها في الراكب","أن مصدرها الهواء الموجود داخل السيارة المنعطفة","أنها غير موجودة، وما تشعر به سببه قصورك الذاتي","أنها رد فعل القوة المركزية وتؤثر فيك أنت نفسك"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 170، 171 — تحديد مصدر القوة، القوة الوهمية'),
('mcq', 7, 'عند توقف سيارة فجأة يندفع الراكب إلى الأمام، وعند انعطافها فجأة يندفع نحو خارج المنعطف. ما الذي يشترك فيه الموقفان؟', null, null, '["يستمر الراكب في الحالتين بقصوره الذاتي دون قوة تدفعه","في الحالتين تؤثر في الراكب قوة حقيقية في اتجاه اندفاعه نفسه","في الحالتين يتسارع الراكب في اتجاه اندفاعه بالنسبة إلى الأرض","في الحالتين يكون سبب الاندفاع قوة الطرد المركزي"]'::jsonb, 'تحليل', 'مقارنة مواقف', 'صعب', 'الكتاب ص 171 — القوة الوهمية، الشكل 6-8'),
('essay', 1, 'فسّر لماذا تُعدّ «قوة الطرد المركزي» قوة وهمية، ثم فسّر اندفاع الراكب نحو خارج المنعطف عندما تنعطف السيارة بسرعة.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 171 — القوة الوهمية، الشكل 6-8'),
('essay', 2, 'ذكر مقال في جريدة: «عندما تتحرك سيارة في منعطف فإن على السائق أن يوازن بين القوة المركزية وقوة الطرد المركزي». اكتب رسالة قصيرة إلى الجريدة تنقد فيها هذا المقال، مستعملًا قوانين نيوتن.', null, null, null, 'تقويم', 'كتابة نقدية', 'صعب', 'الكتاب ص 171 — المراجعة 16'),
('essay', 3, 'يبيّن الشكل (منظورًا من أعلى) سيارة على وشك أن تنعطف نحو اليسار وفيها راكب. (a) صف حركة الراكب بالنسبة إلى الأرض لو كان مقعده أملس تمامًا ولم يلمس الباب بعد. (b) صف حركته كما تبدو لمن في داخل السيارة. (c) حدد القوة الأفقية التي تجعله ينعطف في النهاية واتجاهها.', null, '[{"src":"qimg/phys1/c6l2-o11-e-car.svg","alt":"منظر من أعلى لطريق يتجه إلى أعلى ثم ينعطف إلى اليسار حول نقطة مكتوب عندها «مركز المنعطف». سيارة صفراء على الطريق قبل المنعطف مباشرة، وفيها نقطة تمثل الراكب قرب جانبها الأيمن."}]'::jsonb, null, 'تحليل', 'تحليل حركة', 'متوسط', 'الكتاب ص 171 — القوة الوهمية، الشكل 6-8')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
