select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'بحسب القانون الأول لنيوتن يستمر الراكب في الحركة في خط مستقيم بالسرعة نفسها ما لم تؤثر فيه قوة، والسيارة هي التي تنعطف تحته يسارًا، فيقترب منه الباب الأيمن حتى يدفعه نحو مركز المنعطف.', '["لا يوجد جسم يؤثر بهذه القوة؛ فقوة الطرد المركزي وهمية لا وجود لها.","القوة المركزية تتجه نحو مركز المنعطف لا إلى الخارج.","الباب يدفع الراكب نحو الداخل (نحو المركز) لا إلى الخارج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.263Z"}'::jsonb),
('mcq', 2, 1, 'قوانين نيوتن قادرة على تفسير الحركة الدائرية دون قوة طرد مركزي؛ فهذه القوة لا وجود لها لأنه لا يمكن تحديد مصدرها، وما يشعر به الراكب ناتج عن قصوره الذاتي.', '["لو وُجدت لكانت المحصلة صفرًا، ولتحرك الجسم في خط مستقيم لا في دائرة.","","الأرض لا تؤثر بقوة إلى خارج المنعطف؛ فهي تجذب الأجسام نحو مركزها.","رد فعل الوزن هو قوة جذب الجسم للأرض، ولا علاقة له بالدوران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.263Z"}'::jsonb),
('mcq', 3, 2, 'بغياب القوة الأفقية يستمر الراكب بقصوره الذاتي في خط مستقيم في اتجاه سرعته الأصلية (إلى الأمام)، أي المسار 1، بينما تنعطف السيارة يسارًا؛ فيبدو للراكب كأنه يندفع إلى اليمين.', '["هذا مسار إلى الخارج عموديًا على الحركة، ويتطلب قوة طرد غير موجودة.","متابعة المنعطف تتطلب قوة نحو المركز، وقد فُرض انعدامها.","","هذا مسار نحو المركز، ولا توجد قوة تحرك الراكب نحوه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-21T13:36:33.264Z"}'::jsonb),
('mcq', 4, 0, 'الراكب يحتاج إلى قوة محصلة نحو المركز لينعطف؛ ويوفرها الباب (أو المقعد أو حزام الأمان) بدفعه نحو الداخل. والقوة التي يؤثر بها الراكب في الباب إلى الخارج قوة حقيقية لكنها تؤثر في الباب.', '["","قوة الطرد وهمية، وحتى لو وُجدت فاتجاهها إلى الخارج لا يجعل الراكب ينعطف.","هذه القوة تؤثر في الباب لا في الراكب، فلا تدخل في مخطط الجسم الحر للراكب.","قوة في اتجاه الحركة لا تغير اتجاه السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.264Z"}'::jsonb),
('mcq', 5, 1, 'لا يوجد جسم يؤثر في القمر بقوة إلى الخارج، فقوة الطرد المركزي وهمية. القوة المؤثرة فيه هي قوة التجاذب الكتلي مع الأرض، وهي غير متوازنة وتتجه نحو مركز المدار؛ فهي القوة المركزية التي تغير اتجاه سرعته باستمرار. ولو توازنت القوى المؤثرة فيه لتحرك في خط مستقيم بسرعة ثابتة.', '["تساوي القوتين يجعل المحصلة صفرًا فيتحرك القمر في خط مستقيم لا في دائرة؛ ثم إن قوة الطرد وهمية.","","زوجا التأثير المتبادل يؤثران في جسمين مختلفين، وقوة الطرد وهمية لا جسم يؤثر بها أصلًا.","هذا يفترض وجود قوة الطرد، وهي وهمية؛ ولو كانت المحصلة إلى الخارج لابتعد القمر عن الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.264Z"}'::jsonb),
('mcq', 6, 2, 'إذا لم تستطع تحديد مصدر القوة فإن هذه القوة غير موجودة؛ فاندفاعك نحو الخارج سببه استمرارك في الحركة المستقيمة (القصور الذاتي) بينما تنعطف السيارة.', '["القوى المجالية (كالجاذبية) لها مصدر محدد أيضًا؛ وكل قوة حقيقية لها جسم يؤثر بها.","الهواء داخل السيارة لا يؤثر بقوة تُذكر في الراكب نحو الخارج.","","رد الفعل يؤثر في الجسم الآخر (الباب) لا في الراكب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-21T13:36:33.264Z"}'::jsonb),
('mcq', 7, 0, 'في الحالتين تتغير سرعة السيارة المتجهة (مقدارًا عند التوقف، واتجاهًا عند الانعطاف)، بينما يميل الراكب بحسب القانون الأول لنيوتن إلى الاستمرار بسرعته المتجهة نفسها، فيبدو مندفعًا بالنسبة إلى السيارة، إلى أن يؤثر فيه الحزام أو الباب بقوة.', '["","لا يوجد جسم يدفع الراكب إلى الأمام أو إلى الخارج؛ فهو يحتفظ بحركته.","بالنسبة إلى الأرض يستمر الراكب بالسرعة المتجهة نفسها، والسيارة هي التي تتسارع.","التوقف المفاجئ لا دوران فيه أصلًا، وقوة الطرد وهمية في جميع الحالات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.265Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة الطرد المركزي وهمية لأنه لا يوجد جسم يؤثر بها في الراكب؛ وإذا لم نستطع تحديد مصدر القوة فإنها غير موجودة، وقوانين نيوتن تفسر الحركة الدائرية دونها. تفسير الاندفاع: بحسب القانون الأول لنيوتن يميل الراكب إلى الاستمرار في الحركة في خط مستقيم بسرعته نفسها (القصور الذاتي)، بينما تنعطف السيارة تحته، فيقترب منه جانب السيارة الخارجي، فيبدو للراكب أنه اندفع إلى الخارج. ثم يؤثر الباب أو المقعد فيه بقوة نحو مركز المنعطف فيجعله ينعطف مع السيارة.', '["لا مصدر لقوة الطرد فهي وهمية","القانون الأول: الاستمرار في خط مستقيم","السيارة تنعطف تحت الراكب","الباب يؤثر بقوة نحو المركز"]'::jsonb, '[]'::jsonb, '[{"element":"وهمية القوة مع التعليل","marks":1},{"element":"القصور الذاتي","marks":1},{"element":"دور الباب/المقعد","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل"},{"level":"درجتان","description":"تفسير القصور الذاتي دون دور الباب أو دون تعليل الوهمية"},{"level":"درجة واحدة","description":"ذكر أن القوة وهمية فقط"},{"level":"صفر","description":"عدّ قوة الطرد حقيقية أو لا إجابة"}]'::jsonb, '["القول إن القوة المركزية تدفع الراكب إلى الخارج","تفسير الاندفاع بقوة طرد حقيقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.265Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نص مقترح: «العبارة غير صحيحة فيزيائيًا لسببين: أولًا، لا توجد قوة طرد مركزي؛ فهي قوة وهمية لا يمكن تحديد جسم يؤثر بها، وما يشعر به الركاب سببه قصورهم الذاتي (القانون الأول لنيوتن). ثانيًا، لو كانت القوى المؤثرة في السيارة متوازنة لكانت محصلتها صفرًا، فتتحرك السيارة في خط مستقيم بسرعة ثابتة ولا تنعطف. فالسيارة تنعطف لأن عليها قوة محصلة غير متوازنة نحو مركز المنعطف (يوفرها الاحتكاك بين العجلات والطريق)، مقدارها $F_{\text{المحصلة}} = \frac{mv^2}{r}$ وفق القانون الثاني لنيوتن. وما على السائق إلا أن يضبط سرعته بحيث لا تتجاوز القوة المطلوبة أقصى ما يوفره الاحتكاك.»', '["قوة الطرد وهمية بلا مصدر","التوازن يعني محصلة صفرًا وحركة مستقيمة","الانعطاف يتطلب محصلة نحو المركز (القانون الثاني)","مصدر المحصلة: الاحتكاك","نصيحة صحيحة بضبط السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"نقد وجود قوة الطرد","marks":1},{"element":"نقد فكرة التوازن","marks":1},{"element":"التفسير بالقانون الثاني ومصدر القوة","marks":1},{"element":"صياغة الرسالة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نقد علمي كامل بقوانين نيوتن"},{"level":"2–3 درجات","description":"نقد إحدى الفكرتين مع تفسير صحيح"},{"level":"درجة واحدة","description":"رفض العبارة دون تعليل"},{"level":"صفر","description":"تأييد العبارة أو لا إجابة"}]'::jsonb, '["قبول فكرة التوازن","عدّ القوة المركزية قوة إضافية على الاحتكاك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-21T13:36:33.265Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) بالنسبة إلى الأرض يستمر الراكب في خط مستقيم إلى الأمام بالسرعة نفسها؛ لأنه لا تؤثر فيه قوة أفقية (القانون الأول لنيوتن). (b) لمن داخل السيارة يبدو أن الراكب ينزلق نحو الباب الأيمن (خارج المنعطف)، لأن السيارة تنعطف يسارًا تحته؛ وهذا لا يعني وجود قوة تدفعه إلى الخارج. (c) عندما يصل إلى الباب الأيمن يؤثر الباب فيه بقوة أفقية نحو اليسار، أي نحو مركز المنعطف، وهي القوة المركزية التي تجعله ينعطف مع السيارة.', '["بالنسبة إلى الأرض: خط مستقيم إلى الأمام","داخل السيارة: يبدو منزلقًا إلى الخارج","لا توجد قوة إلى الخارج","قوة الباب نحو مركز المنعطف"]'::jsonb, '[]'::jsonb, '[{"element":"الحركة بالنسبة إلى الأرض","marks":1},{"element":"الحركة كما تبدو في السيارة","marks":1},{"element":"القوة واتجاهها","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الراكب يتحرك إلى اليمين بالنسبة إلى الأرض","جعل قوة الباب إلى الخارج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-21T13:36:33.266Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
