('mcq', 4, 'يكمل عدّاء دورة كاملة حول المضمار الدائري المبيّن في الشكل في 12.5 s بسرعة ثابتة المقدار. ما مقدار سرعته؟', null, '[{"src":"qimg/phys1/c6l2-o12-track.svg","alt":"مضمار دائري رمادي عريض، يمر في وسطه خط متقطع يمثل مسار العدّاء، وفي مركزه نقطة. خط أخضر من المركز إلى المسار في أسفل اليمين مكتوب عنده 40.0 m. نقطة عند أعلى المسار تمثل العدّاء، وسهم رمادي منحنٍ يبين اتجاه حركته."}]'::jsonb, '["$3.20\\ \\text{m/s}$","$10.1\\ \\text{m/s}$","$3.14\\times10^{3}\\ \\text{m/s}$","$20.1\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حساب من شكل', 'متوسط', 'الكتاب ص 169، 181 — الزمن الدوري، التقويم 42'),
('mcq', 5, 'نقطة على طرف عجلة نصف قطرها 0.35 m تتحرك بسرعة مقدارها 11 m/s. ما الزمن الدوري للعجلة؟', null, null, '["$0.032\\ \\text{s}$","$5.0\\ \\text{s}$","$0.10\\ \\text{s}$","$0.20\\ \\text{s}$"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'متوسط', 'الكتاب ص 169 — الزمن الدوري ومقدار السرعة'),
('mcq', 6, 'قمر صناعي يدور حول الأرض في مدار دائري نصف قطره $7.0\times10^{6}\ \text{m}$، ويكمل دورة كاملة كل 100.0 min. ما مقدار سرعته؟', null, null, '["$4.4\\times10^{5}\\ \\text{m/s}$","$7.3\\times10^{3}\\ \\text{m/s}$","$1.2\\times10^{3}\\ \\text{m/s}$","$3.7\\times10^{3}\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'صعب', 'الكتاب ص 169 — الزمن الدوري ومقدار السرعة'),
('mcq', 7, 'يدور القرص المبيّن في الشكل دورة كاملة كل 0.50 s. ما مقدار سرعة النقطة B؟', null, '[{"src":"qimg/phys1/c6l2-o12-disc.svg","alt":"قرص دائري مركزه O، وخط من O إلى أعلى اليمين تقع عليه نقطتان: A في منتصفه وB عند طرفه قرب حافة القرص. مكتوب داخل القرص OA = 0.10 m وOB = 0.20 m. سهم رمادي منحنٍ خارج القرص يبين اتجاه الدوران."}]'::jsonb, '["$1.3\\ \\text{m/s}$","$0.40\\ \\text{m/s}$","$2.5\\ \\text{m/s}$","$5.0\\ \\text{m/s}$"]'::jsonb, 'تحليل', 'حساب من شكل', 'صعب', 'الكتاب ص 169 — الزمن الدوري ومقدار السرعة'),
('essay', 1, 'عرّف الزمن الدوري، واستنتج العلاقة $v = \frac{2\pi r}{\text{T}}$، ثم احسب مقدار سرعة طرف عقرب الثواني في ساعة إذا كان طول العقرب 1.2 cm.', null, null, null, 'تطبيق', 'تعريف وحساب', 'متوسط', 'الكتاب ص 169 — الزمن الدوري ومقدار السرعة'),
('essay', 2, 'عجلة دوّارة في مدينة ألعاب نصف قطرها 25.0 m كما في الشكل، وتكمل دورة كاملة كل 2.00 min بمعدل ثابت. (a) احسب مقدار سرعة راكب في إحدى عرباتها. (b) ما المسافة التي يقطعها خلال 30.0 s؟', null, '[{"src":"qimg/phys1/c6l2-o12-e-wheel.svg","alt":"عجلة دوّارة على شكل دائرة كبيرة محمولة على ساقين مائلتين فوق أرض أفقية، وعليها ثماني عربات صفراء موزعة بانتظام، وتصل المركز بالعربات أشعة رمادية. خط أخضر من المركز إلى الحافة مكتوب عنده 25.0 m. سهم رمادي منحنٍ على يسارها يبين اتجاه الدوران."}]'::jsonb, null, 'تطبيق', 'مسألة', 'متوسط', 'الكتاب ص 169 — الزمن الدوري ومقدار السرعة'),
('essay', 3, 'تدور الأرض حول الشمس في مدار دائري تقريبًا نصف قطره $1.50\times10^{11}\ \text{m}$، وزمنها الدوري 365 يومًا. (a) حوّل الزمن الدوري إلى ثوانٍ. (b) احسب مقدار سرعة الأرض في مدارها. (c) إذا كانت سرعة جسم آخر على المدار نفسه مثلي سرعة الأرض، فكم يكون زمنه الدوري؟', null, null, null, 'تحليل', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 169 — الزمن الدوري ومقدار السرعة')
