from (values
('mcq', 1, 0, 'الزمن الدوري $\text{T}$ هو الزمن اللازم لإكمال دورة كاملة، وخلاله يقطع الجسم مسافة تساوي محيط الدائرة.', '["","هذا يصف عدد الدورات في وحدة الزمن، أما الزمن الدوري فزمن الدورة الواحدة ويقاس بالثانية.","الزمن الدوري يقابل قطع محيط الدائرة $2\\pi r$ كاملًا لا نصف القطر.","نصف الدورة يستغرق نصف الزمن الدوري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.267Z"}'::jsonb),
('mcq', 2, 2, 'في دورة كاملة يقطع الجسم محيط الدائرة $2\pi r$؛ لذلك $v = \frac{2\pi r}{\text{T}}$.', '["هذه مساحة الدائرة لا محيطها.","هذا قطر الدائرة، والجسم يقطع المحيط كاملًا في دورة واحدة.","","هذا نصف المحيط، أي مسافة نصف دورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.267Z"}'::jsonb),
('mcq', 3, 1, '$v = \frac{2\pi r}{\text{T}} = \frac{2\pi (0.30\ \text{m})}{0.50\ \text{s}} = 3.8\ \text{m/s}$.', '["استُعمل $\\pi r$ (نصف المحيط) بدل $2\\pi r$.","","قُسم نصف القطر على الزمن الدوري دون ضربه في $2\\pi$.","ضُرب المحيط في الزمن الدوري بدل القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.267Z"}'::jsonb),
('mcq', 4, 3, '$v = \frac{2\pi r}{\text{T}} = \frac{2\pi (40.0\ \text{m})}{12.5\ \text{s}} = 20.1\ \text{m/s}$.', '["قُسم نصف القطر على الزمن دون ضربه في $2\\pi$.","استُعمل نصف المحيط $\\pi r$.","ضُرب المحيط في الزمن الدوري بدل القسمة عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.268Z"}'::jsonb),
('mcq', 5, 3, '$\text{T} = \frac{2\pi r}{v} = \frac{2\pi (0.35\ \text{m})}{11\ \text{m/s}} = 0.20\ \text{s}$.', '["قُسم نصف القطر على السرعة دون ضربه في $2\\pi$.","هذا مقلوب الناتج الصحيح: $\\frac{v}{2\\pi r}$.","استُعمل نصف المحيط $\\pi r$ بدل المحيط كاملًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.268Z"}'::jsonb),
('mcq', 6, 1, '$\text{T} = 100.0 \times 60 = 6.000\times10^{3}\ \text{s}$؛ $v = \frac{2\pi (7.0\times10^{6}\ \text{m})}{6.000\times10^{3}\ \text{s}} = 7.3\times10^{3}\ \text{m/s}$.', '["لم يُحوَّل الزمن الدوري من الدقائق إلى الثواني.","","قُسم نصف القطر على الزمن دون ضربه في $2\\pi$.","استُعمل نصف المحيط $\\pi r$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.268Z"}'::jsonb),
('mcq', 7, 2, 'النقطتان لهما الزمن الدوري نفسه، ونصف قطر مسار B هو 0.20 m؛ $v_B = \frac{2\pi (0.20\ \text{m})}{0.50\ \text{s}} = 2.5\ \text{m/s}$، وهي مثلا سرعة A لأن بُعدها مثلا بُعد A.', '["هذه سرعة النقطة A التي بُعدها 0.10 m، لا النقطة B.","قُسم البُعد على الزمن الدوري دون ضربه في $2\\pi$.","","عُوِّض ضعف البُعد (0.40 m) كأنه نصف القطر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.269Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الزمن الدوري $\text{T}$ هو الزمن اللازم لإكمال دورة كاملة. خلال هذا الزمن يقطع الجسم مسافة تساوي محيط الدائرة $2\pi r$، ولأن مقدار السرعة = المسافة ÷ الزمن فإن $v = \frac{2\pi r}{\text{T}}$. عقرب الثواني يكمل دورة كل 60 s، و$r = 1.2\ \text{cm} = 0.012\ \text{m}$: $v = \frac{2\pi (0.012\ \text{m})}{60\ \text{s}} = 1.3\times10^{-3}\ \text{m/s}$.', '["تعريف الزمن الدوري","المسافة في دورة = $2\\pi r$","$v = \\frac{2\\pi r}{\\text{T}}$","T = 60 s وتحويل r","$v = 1.3\\times10^{-3}\\ \\text{m/s}$"]'::jsonb, '["$r = 0.012\\ \\text{m}$، $\\text{T} = 60\\ \\text{s}$","$v = \\frac{2\\pi \\times 0.012}{60} = 1.3\\times10^{-3}\\ \\text{m/s}$"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الاستنتاج","marks":1},{"element":"تحديد T والتحويل","marks":1},{"element":"الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف واستنتاج وحساب صحيح"},{"level":"2–3 درجات","description":"خطأ في التحويل أو غياب الاستنتاج"},{"level":"درجة واحدة","description":"التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الزمن الدوري لعقرب الثواني 1 s","عدم تحويل cm إلى m"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.269Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\text{T} = 2.00\ \text{min} = 120\ \text{s}$؛ $v = \frac{2\pi r}{\text{T}} = \frac{2\pi (25.0\ \text{m})}{120\ \text{s}} = 1.31\ \text{m/s}$. (b) المسافة $= v t = (1.31\ \text{m/s})(30.0\ \text{s}) = 39.3\ \text{m}$؛ وهي ربع المحيط، لأن 30.0 s ربع الزمن الدوري.', '["تحويل T إلى ثوانٍ","$v = 1.31\\ \\text{m/s}$","المسافة 39.3 m"]'::jsonb, '["$\\text{T} = 120\\ \\text{s}$","$v = \\frac{2\\pi \\times 25.0}{120} = 1.31\\ \\text{m/s}$","$d = 1.31 \\times 30.0 = 39.3\\ \\text{m}$ (أو $\\frac{1}{4}\\times 2\\pi \\times 25.0$)"]'::jsonb, '[{"element":"التحويل","marks":1},{"element":"السرعة","marks":1},{"element":"المسافة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع الأجزاء صحيحة"},{"level":"درجتان","description":"خطأ واحد"},{"level":"درجة واحدة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل الدقائق إلى ثوانٍ","استعمال القطر بدل نصف القطر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.269Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $\text{T} = 365 \times 24 \times 3600 = 3.15\times10^{7}\ \text{s}$. (b) $v = \frac{2\pi r}{\text{T}} = \frac{2\pi (1.50\times10^{11}\ \text{m})}{3.15\times10^{7}\ \text{s}} = 2.99\times10^{4}\ \text{m/s}$. (c) على المدار نفسه $\text{T} = \frac{2\pi r}{v}$، فمضاعفة السرعة تجعل الزمن الدوري نصف قيمته: 182.5 يومًا تقريبًا ($1.58\times10^{7}\ \text{s}$).', '["$\\text{T} = 3.15\\times10^{7}\\ \\text{s}$","$v = 2.99\\times10^{4}\\ \\text{m/s}$","الزمن الدوري يصبح النصف"]'::jsonb, '["$\\text{T} = 365 \\times 86400 = 3.15\\times10^{7}\\ \\text{s}$","$v = \\frac{2\\pi \\times 1.50\\times10^{11}}{3.15\\times10^{7}} = 2.99\\times10^{4}\\ \\text{m/s}$","$\\text{T} \\propto \\frac{1}{v}$ عند ثبات $r$"]'::jsonb, '[{"element":"التحويل","marks":1},{"element":"السرعة","marks":2},{"element":"الاستدلال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"خطأ في التحويل أو الاستدلال"},{"level":"درجة واحدة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان التحويل إلى ثوانٍ","الخلط بين الأسس عند القسمة","القول إن الزمن الدوري يتضاعف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.270Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
