from (values
('mcq', 1, 'يتحرك جسم حركة دائرية منتظمة عكس اتجاه عقارب الساعة. أيّ الأسهم المرقمة في الشكل يمثل اتجاه سرعته المتجهة عند الموقع المبيّن؟', null, '[{"src":"qimg/phys1/c6l2-o13-vel.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ أسفل يسارها يبين الدوران عكس عقارب الساعة. جسم على الدائرة في أعلى يمينها (بزاوية 45 درجة)، يخرج منه أربعة أسهم سوداء مرقمة: السهم 1 إلى أعلى اليمين على امتداد نصف القطر بعيدًا عن المركز، والسهم 2 إلى أسفل اليسار نحو المركز، والسهم 3 إلى أعلى اليسار مماس للدائرة، والسهم 4 إلى أسفل اليمين مماس للدائرة."}]'::jsonb, '["السهم 1","السهم 3","السهم 2","السهم 4"]'::jsonb, 'فهم', 'تحديد اتجاه من شكل', 'سهل', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('mcq', 2, 'يتحرك جسم حركة دائرية منتظمة مع اتجاه عقارب الساعة، وهو الآن عند الموقع المبيّن على يسار المسار. أيّ الأسهم المرقمة له اتجاه متجه الموقع $\boldsymbol{r}$ للجسم (المرسوم من مركز الدائرة إلى الجسم)؟', null, '[{"src":"qimg/phys1/c6l2-o13-acc.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ أعلى يمينها يبين الدوران مع عقارب الساعة. جسم على الدائرة في يسارها أسفل الخط الأفقي بقليل، يخرج منه أربعة أسهم سوداء مرقمة: السهم 1 إلى أعلى مماس للدائرة، والسهم 2 إلى اليسار وقليلًا إلى أسفل بعيدًا عن المركز، والسهم 3 إلى أسفل مماس للدائرة، والسهم 4 إلى اليمين وقليلًا إلى أعلى نحو المركز."}]'::jsonb, '["السهم 1","السهم 2","السهم 3","السهم 4"]'::jsonb, 'فهم', 'تحديد اتجاه من شكل', 'سهل', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('mcq', 3, 'متجه السرعة لجسم يتحرك حركة دائرية منتظمة يكون دائمًا:', null, null, '["مماسًا للمسار وعموديًا على متجه الموقع","موازيًا لمتجه الموقع ومتجهًا بعيدًا عن المركز","متجهًا نحو مركز الدائرة في اتجاه التسارع","يصنع زاوية $45^\\circ$ مع متجه الموقع"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('mcq', 4, 'ما مقدار الزاوية بين متجه السرعة ومتجه التسارع لجسم يتحرك حركة دائرية منتظمة؟', null, null, '["$0^\\circ$","$180^\\circ$","$90^\\circ$","$45^\\circ$"]'::jsonb, 'فهم', 'استنتاج زاوية', 'متوسط', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('mcq', 5, 'جسم يتحرك حركة دائرية منتظمة عكس اتجاه عقارب الساعة. أيّ المخططات الآتية يمثل اتجاهي سرعته وتسارعه عند الموقع المبيّن تمثيلًا صحيحًا؟', null, '[{"src":"qimg/phys1/c6l2-o13-panels.svg","alt":"أربعة مخططات مرقمة من 1 إلى 4، في كل منها دائرة مركزها نقطة وسهم رمادي منحنٍ أسفلها يبين الدوران عكس عقارب الساعة، وجسم عند أقصى يمين الدائرة يخرج منه سهم أحمر مكتوب عنده v وسهم بنفسجي مكتوب عنده ac. المخطط 1: v إلى أعلى وac أفقي إلى اليسار نحو المركز. المخطط 2: v إلى أعلى وac أفقي إلى اليمين بعيدًا عن المركز. المخطط 3: v أفقي إلى اليسار نحو المركز وac إلى أعلى. المخطط 4: v إلى أعلى وac إلى أعلى أيضًا."}]'::jsonb, '["المخطط 2","المخطط 3","المخطط 1","المخطط 4"]'::jsonb, 'فهم', 'تفسير مخطط', 'متوسط', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('mcq', 6, 'جسم يتحرك حركة دائرية منتظمة مع اتجاه عقارب الساعة (منظورًا من أعلى). ما اتجاها سرعته وتسارعه عندما يكون عند الموقع $Q$ في أقصى غرب الدائرة؟', null, '[{"src":"qimg/phys1/c6l2-o13-compass.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ عند يمينها العلوي يبين الدوران مع عقارب الساعة. جسم عند أقصى يسار الدائرة مكتوب عنده Q. وفي أعلى يمين الشكل بوصلة: شمال إلى أعلى، وجنوب إلى أسفل، وشرق إلى اليمين، وغرب إلى اليسار."}]'::jsonb, '["السرعة نحو الشمال، والتسارع نحو الشرق","السرعة نحو الجنوب، والتسارع نحو الشرق","السرعة نحو الشمال، والتسارع نحو الغرب","السرعة نحو الشرق، والتسارع نحو الشمال"]'::jsonb, 'تطبيق', 'تحديد اتجاهات', 'صعب', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('mcq', 7, 'لجسم يتحرك حركة دائرية منتظمة ثلاثة متجهات: متجه الموقع $\boldsymbol{r}$ (من المركز إلى الجسم)، والسرعة $\boldsymbol{v}$، والتسارع $\boldsymbol{a}_{\text{C}}$. أيّ متجهين منها يقعان على خط عمل واحد في كل لحظة؟', null, null, '["متجه السرعة ومتجه التسارع، وهما في الاتجاه نفسه","متجه الموقع ومتجه السرعة، وهما في الاتجاه نفسه","لا يوجد متجهان منها على خط عمل واحد في أي لحظة","متجه الموقع ومتجه التسارع، وهما متعاكسان"]'::jsonb, 'تحليل', 'مقارنة متجهات', 'صعب', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('essay', 1, 'يبيّن الشكل جسمًا يتحرك حركة دائرية منتظمة عكس اتجاه عقارب الساعة، مرّ بالمواقع A وB وC وD. ارسم عند كل موقع متجه السرعة ومتجه التسارع، ثم صف العلاقة بين اتجاهيهما واتجاه متجه الموقع.', null, '[{"src":"qimg/phys1/c6l2-o13-e-points.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ أعلاها يبين الدوران عكس عقارب الساعة. أربع نقاط على الدائرة: A في أعلى اليمين، وB في أعلى اليسار، وC في أسفل اليسار، وD في أسفل اليمين، كلها بزوايا 45 درجة من المحورين."}]'::jsonb, null, 'فهم', 'رسم متجهات', 'متوسط', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية'),
('essay', 2, 'فسّر لماذا يكون متجه السرعة لجسم في حركة دائرية منتظمة عموديًا على متجه الموقع، مستعينًا بمتجه الإزاحة $\Delta\boldsymbol{r}$ خلال فترة زمنية قصيرة جدًا.', null, null, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 168 — الشكل 6-5'),
('essay', 3, 'كرة مربوطة بخيط تدور في دائرة أفقية بسرعة ثابتة المقدار. حدد اتجاه سرعتها واتجاه تسارعها عند أي لحظة، واذكر الزاوية بينهما، ثم قارن بين متجهي سرعتها عند موقعين متقابلين قطريًا.', null, null, null, 'فهم', 'تحديد ومقارنة', 'متوسط', 'الكتاب ص 168، 179 — اتجاه السرعة والتسارع في الحركة الدائرية')
