('mcq', 1, 1, 'السرعة المتجهة مماسية للمسار وعمودية على متجه الموقع وفي اتجاه الحركة؛ ومع الدوران عكس عقارب الساعة يكون اتجاه المماس عند هذا الموقع إلى أعلى اليسار، وهو السهم 3.', '["هذا السهم على امتداد نصف القطر إلى الخارج، أي في اتجاه متجه الموقع لا السرعة.","","هذا السهم نحو المركز، وهو اتجاه التسارع المركزي لا السرعة.","هذا السهم مماسي لكنه عكس اتجاه الدوران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-21T13:36:33.271Z"}'::jsonb),
('mcq', 2, 1, 'متجه الموقع يبدأ من مركز الدائرة وينتهي عند الجسم، فاتجاهه على امتداد نصف القطر بعيدًا عن المركز، وهو السهم 2؛ أما السرعة (السهم 1) فعمودية عليه، والتسارع المركزي (السهم 4) عكسه.', '["السهم 1 مماسي في اتجاه الحركة، فهو اتجاه السرعة المتجهة، وهي عمودية على متجه الموقع لا موازية له.","","السهم 3 مماسي عكس اتجاه الحركة، فهو عمودي على متجه الموقع لا موازٍ له.","السهم 4 يتجه نحو المركز، وهو اتجاه التسارع المركزي، أي عكس اتجاه متجه الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-21T13:36:33.271Z"}'::jsonb),
('mcq', 3, 0, 'متجه السرعة عمودي على متجه الموقع، أي مماس لمحيط الدائرة، ويبقى مقداره ثابتًا بينما يتغير اتجاهه.', '["","متجه الموقع نصف قطري، والسرعة عمودية عليه لا موازية له.","المتجه نحو المركز هو التسارع، والسرعة عمودية عليه.","الزاوية بين السرعة ومتجه الموقع $90^\\circ$ دائمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-21T13:36:33.271Z"}'::jsonb),
('mcq', 4, 2, 'السرعة مماسية والتسارع نحو المركز (على امتداد نصف القطر)، والمماس عمودي على نصف القطر؛ فالزاوية بينهما $90^\circ$.', '["لو كانا في الاتجاه نفسه لزاد مقدار السرعة.","لو كانا متعاكسين لتناقص مقدار السرعة.","","لو كانت الزاوية $45^\\circ$ لكان للتسارع مركّبة تغير مقدار السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-21T13:36:33.272Z"}'::jsonb),
('mcq', 5, 2, 'عند أقصى يمين الدائرة مع الدوران عكس عقارب الساعة تكون السرعة مماسية إلى أعلى، والتسارع نحو المركز أي إلى اليسار؛ وهذا ما يبيّنه المخطط 1.', '["السرعة صحيحة، لكن التسارع فيه يتجه إلى الخارج بعيدًا عن المركز.","الاتجاهان مقلوبان: السرعة فيه نحو المركز والتسارع مماسي.","","التسارع فيه مماسي في اتجاه السرعة، فيزيد مقدارها ولا تبقى الحركة منتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-21T13:36:33.272Z"}'::jsonb),
('mcq', 6, 0, 'مع عقارب الساعة يتحرك الجسم من الأسفل إلى اليسار ثم إلى الأعلى؛ فعند أقصى الغرب تكون سرعته المماسية نحو الشمال، والمركز يقع شرقه فيكون التسارع نحو الشرق.', '["","التسارع صحيح، لكن الدوران مع عقارب الساعة يجعل الحركة عند أقصى الغرب نحو الشمال.","السرعة صحيحة، لكن التسارع نحو المركز، والمركز شرق الموقع $Q$.","هذا يبادل بين الاتجاهين؛ فالشرق اتجاه المركز أي اتجاه التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-21T13:36:33.272Z"}'::jsonb),
('mcq', 7, 3, 'متجه الموقع يتجه من المركز إلى الجسم، والتسارع المركزي من الجسم إلى المركز؛ فهما على امتداد نصف القطر نفسه ومتعاكسان، بينما السرعة عمودية عليهما.', '["السرعة مماسية والتسارع نصف قطري، فهما متعامدان.","السرعة عمودية على متجه الموقع دائمًا.","متجه الموقع والتسارع كلاهما على امتداد نصف القطر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.273Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند كل موقع: يُرسم متجه السرعة مماسًا للدائرة في اتجاه الدوران (عكس عقارب الساعة)، فعند A (أعلى اليمين) يتجه إلى أعلى اليسار، وعند B (أعلى اليسار) إلى أسفل اليسار، وعند C (أسفل اليسار) إلى أسفل اليمين، وعند D (أسفل اليمين) إلى أعلى اليمين؛ ويُرسم متجه التسارع من الجسم نحو المركز. العلاقة: السرعة عمودية على متجه الموقع (مماسية)، والتسارع على امتداد متجه الموقع لكن بعكس اتجاهه (نحو المركز)؛ فالسرعة والتسارع متعامدان دائمًا، وأطوال متجهات السرعة متساوية وكذلك أطوال متجهات التسارع.', '["السرعة مماسية في اتجاه الدوران عند كل موقع","التسارع نحو المركز عند كل موقع","السرعة عمودية على متجه الموقع","التسارع عكس متجه الموقع","تساوي الأطوال"]'::jsonb, '[]'::jsonb, '[{"element":"رسم السرعات","marks":1},{"element":"رسم التسارعات","marks":1},{"element":"علاقة السرعة بالموقع","marks":1},{"element":"علاقة التسارع بالموقع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم صحيح ووصف كامل"},{"level":"2–3 درجات","description":"رسم صحيح لأحد المتجهين أو وصف ناقص"},{"level":"درجة واحدة","description":"وصف لفظي صحيح دون رسم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم السرعة عكس اتجاه الدوران","رسم التسارع إلى الخارج","رسم أطوال مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.273Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السرعة المتجهة المتوسطة $\boldsymbol{\bar{v}} = \frac{\Delta\boldsymbol{r}}{\Delta t}$ لها اتجاه الإزاحة $\Delta\boldsymbol{r}$ نفسه، و$\Delta\boldsymbol{r}$ هو الوتر الواصل بين موقعين على الدائرة. كلما صغرت الفترة الزمنية اقترب الموقعان، واقترب الوتر من أن يكون مماسًا للدائرة عند موقع الجسم. والمماس للدائرة عمودي على نصف القطر (متجه الموقع)؛ لذا فإن متجه السرعة اللحظية مماسي وعمودي على متجه الموقع.', '["السرعة في اتجاه $\\Delta\\boldsymbol{r}$","$\\Delta\\boldsymbol{r}$ وتر بين موقعين","الوتر يقترب من المماس عند تصغير الفترة","المماس عمودي على نصف القطر"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه السرعة واتجاه الإزاحة","marks":1},{"element":"تحول الوتر إلى مماس","marks":1},{"element":"تعامد المماس مع نصف القطر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل"},{"level":"درجتان","description":"تفسير يغفل خطوة"},{"level":"درجة واحدة","description":"ذكر التعامد دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين طول متجه الموقع والإزاحة","القول إن السرعة على امتداد نصف القطر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-21T13:36:33.273Z"}'::jsonb),
('essay', 3, null::int, null, null, 'السرعة مماسية للدائرة في اتجاه الدوران، والتسارع نحو مركز الدائرة على امتداد الخيط؛ والزاوية بينهما $90^\circ$. عند موقعين متقابلين قطريًا يكون لمتجهي السرعة المقدار نفسه لكنهما متعاكسان في الاتجاه (والأمر نفسه لمتجهي التسارع)؛ أي أن السرعة المتجهة تغيرت مع أن مقدارها ثابت.', '["السرعة مماسية","التسارع نحو المركز","الزاوية $90^\\circ$","عند الموقعين المتقابلين: مقدار واحد واتجاهان متعاكسان"]'::jsonb, '[]'::jsonb, '[{"element":"الاتجاهان","marks":1},{"element":"الزاوية","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السرعة متساوية عند الموقعين لتساوي مقدارها","جعل التسارع على امتداد السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.274Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
