insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L2-O14'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'عند حل مسائل الحركة الدائرية المنتظمة بالقانون الثاني لنيوتن، كيف يُختار المحوران؟', null, null, '["محوران أفقي ورأسي ثابتان لا يتغيران مع حركة الجسم","المحور c بعيدًا عن المركز، والمحور tang نحو المركز","المحور c نحو المركز، وtang مع السرعة المماسية","المحور c في اتجاه السرعة، والمحور tang نحو المركز"]'::jsonb, 'تذكر', 'تذكر طريقة', 'سهل', 'الكتاب ص 169، 170 — القانون الثاني لنيوتن في الحركة الدائرية، المحوران c وtang'),
('mcq', 2, 'ما مقدار محصلة القوى على المحور المماسي tang لجسم يتحرك حركة دائرية منتظمة؟', null, null, '["صفر؛ لأن مقدار السرعة ثابت","$ma_{\\text{C}}$؛ لأن الجسم يتسارع تسارعًا مركزيًا","$mg$؛ لأن الوزن يؤثر في الجسم دائمًا","$mv$؛ لأن الجسم يتحرك على هذا المحور"]'::jsonb, 'فهم', 'تطبيق القانون على محور', 'متوسط', 'الكتاب ص 169، 170 — القانون الثاني لنيوتن في الحركة الدائرية، المحوران c وtang'),
('mcq', 3, 'جسم يدور حركة دائرية منتظمة عكس اتجاه عقارب الساعة (منظورًا من أعلى)، وهو الآن عند الموقع $S$ في أقصى شرق الدائرة. ما الاتجاه الموجب لكل من المحورين c وtang عند هذه اللحظة؟', null, '[{"src":"qimg/phys1/c6l2-o14-axes.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ عند يسارها العلوي يبين الدوران عكس عقارب الساعة. جسم عند أقصى يمين الدائرة مكتوب عنده S. وفي أعلى يمين الشكل بوصلة: شمال إلى أعلى، وجنوب إلى أسفل، وشرق إلى اليمين، وغرب إلى اليسار."}]'::jsonb, '["$+\\text{c}$ نحو الشرق، و$+\\text{tang}$ نحو الشمال","$+\\text{c}$ نحو الغرب، و$+\\text{tang}$ نحو الجنوب","$+\\text{c}$ نحو الشمال، و$+\\text{tang}$ نحو الغرب","$+\\text{c}$ نحو الغرب، و$+\\text{tang}$ نحو الشمال"]'::jsonb, 'تطبيق', 'اختيار المحاور', 'سهل', 'الكتاب ص 169، 170 — القانون الثاني لنيوتن في الحركة الدائرية، المحوران c وtang'),
('mcq', 4, 'كرة كتلتها 0.40 kg مربوطة بخيط طرفه الآخر مثبت في مركز طاولة أفقية ملساء، وتدور كما في الشكل (منظورًا من أعلى) بسرعة ثابتة المقدار 2.0 m/s. تؤثر في الكرة ثلاث قوى: وزنها، والقوة العمودية من الطاولة، وقوة الشد في الخيط. ما مقدار قوة الشد في الخيط؟', null, '[{"src":"qimg/phys1/c6l2-o14-table.svg","alt":"منظر من أعلى لدائرة متقطعة تمثل مسار الكرة، في مركزها حلقة صغيرة تمثل نقطة التثبيت، وخط من المركز إلى كرة رمادية على الدائرة في أعلى يمينها مكتوب عنده 0.80 m. سهم رمادي منحنٍ يبين اتجاه الدوران."}]'::jsonb, '["$5.9\\ \\text{N}$","$2.0\\ \\text{N}$","$3.9\\ \\text{N}$","$1.0\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 170 — المثال 2'),
('mcq', 5, 'كرة كتلتها 0.60 kg مربوطة بخيط طوله 0.75 m تدور في دائرة رأسية، ومقدار سرعتها عند أدنى نقطة 3.0 m/s. يبيّن الشكل مخطط الجسم الحر للكرة عند تلك النقطة. ما مقدار قوة الشد في الخيط عندها؟', null, '[{"src":"qimg/phys1/c6l2-o14-bottom.svg","alt":"مخطط الجسم الحر: نقطة تمثل الكرة، يخرج منها سهم أزرق طويل إلى أعلى مكتوب عنده FT، وسهم أزرق أقصر منه (أقل من نصف طوله) إلى أسفل مكتوب عنده Fg. وعلى يمين المخطط سهم رمادي إلى أعلى مكتوب عنده $+\\text{c}$."}]'::jsonb, '["$13\\ \\text{N}$","$7.2\\ \\text{N}$","$1.3\\ \\text{N}$","$5.9\\ \\text{N}$"]'::jsonb, 'تحليل', 'تطبيق القانون الثاني على محور', 'صعب', 'الكتاب ص 169، 182 — القانون الثاني في الحركة الدائرية، التقويم 49'),
('mcq', 6, 'سيارة كتلتها $m$ تسلك منعطفًا أفقيًا مستويًا نصف قطره $r$ بسرعة ثابتة المقدار $v$. أيّ المعادلات الآتية تمثل القانون الثاني لنيوتن على المحور c؟', null, null, '["$F_{\\text{N}} = \\frac{mv^2}{r}$","$f_{f} - F_g = \\frac{mv^2}{r}$","$f_{f} = \\frac{mv}{r}$","$f_{f} = \\frac{mv^2}{r}$"]'::jsonb, 'تطبيق', 'كتابة معادلة الحركة', 'متوسط', 'الكتاب ص 169، 170 — القانون الثاني لنيوتن في الحركة الدائرية، المحوران c وtang'),
('mcq', 7, 'سيارة تسلك منعطفًا أفقيًا مستويًا نصف قطره 60 m بسرعة ثابتة المقدار 18 m/s. ما أقل معامل احتكاك سكوني بين العجلات والطريق يمنع انزلاقها؟', null, null, '["5.4","0.55","0.031","1.8"]'::jsonb, 'تطبيق', 'حساب بالمحورين', 'صعب', 'الكتاب ص 171 — المسألة 11'),
('essay', 1, 'أنت تجلس في المقعد الخلفي لسيارة تنعطف نحو اليمين بسرعة ثابتة المقدار. ارسم نموذج الجسيم النقطي ومخطط الجسم الحر لك (في المستوى الأفقي)، مبيّنًا المحورين c وtang، ثم أجب: (a) ما اتجاه تسارعك؟ (b) ما اتجاه القوة المحصلة المؤثرة فيك، وما مصدرها؟', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'متوسط', 'الكتاب ص 171 — المراجعة 14'),
('essay', 2, 'حجر كتلته 40.0 g مثبت في نهاية خيط طوله 0.60 m، ويدور في مسار دائري أفقي بسرعة ثابتة المقدار 2.2 m/s (أهمل وزن الحجر بحيث يبقى الخيط أفقيًا). (a) اختر المحورين المناسبين وارسم مخطط الجسم الحر للحجر في المستوى الأفقي. (b) اكتب القانون الثاني لنيوتن على كل من المحورين. (c) احسب مقدار قوة الشد في الخيط.', null, null, null, 'تطبيق', 'تطبيق القانون الثاني على محورين', 'سهل', 'الكتاب ص 170، 171 — المحوران c وtang، المراجعة 15'),
('essay', 3, 'كرة كتلتها 0.50 kg مربوطة بخيط طوله 0.60 m، تدور في دائرة رأسية كما في الشكل، ومقدار سرعتها 4.0 m/s عند كل من النقطة العليا والنقطة السفلى. (a) ارسم مخطط الجسم الحر للكرة عند كل من النقطتين وحدد اتجاه $+\text{c}$. (b) احسب قوة الشد في الخيط عند كل نقطة. (c) فسّر لماذا يختلف الشد بين النقطتين.', null, '[{"src":"qimg/phys1/c6l2-o14-e-vert.svg","alt":"دائرة رأسية متقطعة في مركزها حلقة صغيرة، وخط رأسي من المركز إلى كرة رمادية عند أعلى الدائرة مكتوب فوقها «النقطة العليا»، وخط من المركز إلى كرة رمادية عند أسفل الدائرة مكتوب تحتها «النقطة السفلى». ومكتوب بجانب الخط العلوي 0.60 m. سهم رمادي منحنٍ على يسار الدائرة يبين اتجاه الدوران."}]'::jsonb, null, 'تحليل', 'تطبيق القانون الثاني في موقعين', 'صعب', 'الكتاب ص 170، 182 — المحوران c وtang، التقويم 49')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
