('mcq', 1, 'يتحرك قارب بسرعة 5.0 m/s نحو الشمال بالنسبة إلى ماء نهر، ويجري الماء بسرعة 2.0 m/s نحو الشرق بالنسبة إلى الضفة. يبيّن الشكل الآتي المتجهين مرسومين بمقياس رسم بطريقة الرأس إلى الذيل، حيث يرمز b للقارب، وw للماء، وE للأرض (الضفة). ما مقدار سرعة القارب بالنسبة إلى الضفة $v_{b/E}$؟', null, '[{"src":"qimg/phys1/c6l3-o01-boat.svg","alt":"مخطط متجهات بمقياس رسم: من نقطة سوداء في الأسفل سهم أحمر رأسي إلى أعلى (نحو الشمال) مكتوب بجانبه v b/w و5.0 m/s، ومن رأسه سهم أحمر أفقي أقصر إلى اليمين (نحو الشرق) مكتوب فوقه v w/E و2.0 m/s. في أسفل اليمين سهمان يدلان على الشمال (أعلى) والشرق (يمين). لا يظهر المتجه المحصل."}]'::jsonb, '["5.4 m/s","7.0 m/s","3.0 m/s","4.6 m/s"]'::jsonb, 'تطبيق', 'حساب مقدار سرعة نسبية من سرعتين متعامدتين', 'سهل', 'الكتاب ص 173–174 — المثال 3 والمسألة 21'),
('mcq', 2, 'تطير طائرة بسرعة 150 km/h نحو الشمال بالنسبة إلى الهواء، وتهب رياح بسرعة 45 km/h نحو الشرق بالنسبة إلى الأرض. ما اتجاه سرعة الطائرة المتجهة بالنسبة إلى الأرض؟', null, null, '["$73^\\circ$ شرق الشمال","$17^\\circ$ غرب الشمال","$17^\\circ$ شرق الشمال","$73^\\circ$ غرب الشمال"]'::jsonb, 'تطبيق', 'تحديد اتجاه سرعة نسبية', 'سهل', 'الكتاب ص 173–174 — المثال 3 والمسألة 21'),
('mcq', 3, 'يريد طيار الوصول إلى مطار يقع على بعد $3.60\times10^{2}\ \text{km}$ جنوبًا خلال 2.00 h، وتهب رياح من الغرب (نحو الشرق) بسرعة 40.0 km/h بالنسبة إلى الأرض. ما مقدار السرعة التي يجب أن تطير بها الطائرة بالنسبة إلى الهواء؟', null, null, '["175 km/h","220 km/h","140 km/h","184 km/h"]'::jsonb, 'تطبيق', 'إيجاد السرعة اللازمة بالنسبة إلى الهواء', 'صعب', 'الكتاب ص 182 — السؤال 45'),
('mcq', 4, 'رُسم في الشكل الآتي متجه سرعة قارب بالنسبة إلى الماء $\boldsymbol{v}_{b/w}$ ومتجه سرعة الماء بالنسبة إلى الضفة $\boldsymbol{v}_{w/E}$ على شبكة يمثل طول ضلع كل مربع فيها 1.0 m/s. ما مقدار سرعة القارب بالنسبة إلى الضفة؟', null, '[{"src":"qimg/phys1/c6l3-o01-grid.svg","alt":"شبكة مربعات مع محورين +x إلى اليمين و+y إلى أعلى من نقطة الأصل. سهم أحمر v b/w من الأصل إلى النقطة التي تبعد مربعين يمينًا وأربعة مربعات إلى أعلى، ومن رأسه سهم أحمر أفقي v w/E طوله ثلاثة مربعات إلى اليمين، فينتهي عند النقطة (5، 4) مربعات. لا يظهر المتجه المحصل."}]'::jsonb, '["7.5 m/s","6.4 m/s","9.0 m/s","4.5 m/s"]'::jsonb, 'تطبيق', 'قراءة متجهات سرعة على شبكة وجمعها', 'سهل', 'الكتاب ص 174 — مفتاح التحليل: رسم مثلث السرعات'),
('mcq', 5, 'يوجّه ملاح قاربه بحيث يعبر نهرًا في خط مستقيم عمودي على الضفتين. إذا كانت سرعة القارب بالنسبة إلى الماء 5.0 m/s، وسرعة الماء بالنسبة إلى الضفة 2.5 m/s موازية للضفتين، فما مقدار سرعة القارب بالنسبة إلى الضفة؟', null, null, '["5.6 m/s","2.5 m/s","4.3 m/s","7.5 m/s"]'::jsonb, 'تحليل', 'تحليل مثلث سرعات يكون فيه المعلوم هو الوتر', 'متوسط', 'الكتاب ص 175، 182 — السؤالان 26 و47'),
('mcq', 6, 'يبيّن الشكل الآتي، بمقياس رسم، سرعة طائرة بالنسبة إلى الهواء $2.20\times10^{2}\ \text{km/h}$ نحو الشرق، وسرعة الرياح بالنسبة إلى الأرض 50.0 km/h في اتجاه يصنع $45^\circ$ شمال الشرق. ما مقدار سرعة الطائرة بالنسبة إلى الأرض؟', null, '[{"src":"qimg/phys1/c6l3-o01-wind45.svg","alt":"مخطط متجهات بمقياس رسم: من نقطة سوداء سهم أحمر طويل أفقي إلى اليمين (الشرق) مكتوب تحته v الطائرة بالنسبة إلى الهواء وفوقه 2.20×10² km/h، ومن رأسه سهم أحمر قصير يميل إلى أعلى اليمين مكتوب عنده 50.0 km/h وv الهواء بالنسبة إلى الأرض، وبينه وبين امتداد أفقي متقطع قوس زاوية مكتوب عنده 45 درجة. في أعلى اليسار سهما الشمال والشرق. لا يظهر المتجه المحصل."}]'::jsonb, '["270 km/h","226 km/h","170 km/h","258 km/h"]'::jsonb, 'تحليل', 'جمع سرعتين غير متعامدتين بالمركبات', 'صعب', 'الكتاب ص 175 — السؤال 25'),
('mcq', 7, 'يتحرك قارب بسرعة 3.0 m/s نحو الشرق بالنسبة إلى الماء، ودحرج راكب كرة على سطحه بسرعة 1.5 m/s نحو الشمال بالنسبة إلى القارب، كما في الشكل الآتي، حيث يرمز m للكرة، وb للقارب، وw للماء. ما الزاوية التي يصنعها اتجاه سرعة الكرة بالنسبة إلى الماء مع اتجاه الشرق؟', null, '[{"src":"qimg/phys1/c6l3-o01-angle.svg","alt":"مخطط متجهات بمقياس رسم: من نقطة سوداء سهم أحمر أفقي إلى اليمين (الشرق) مكتوب فوقه 3.0 m/s وتحته v b/w، ومن رأسه سهم أحمر رأسي إلى أعلى (الشمال) طوله نصف الأول مكتوب بجانبه v m/b و1.5 m/s. في أعلى اليسار سهما الشمال والشرق. لا يظهر المتجه المحصل."}]'::jsonb, '["$27^\\circ$ شمال الشرق","$63^\\circ$ شمال الشرق","$60^\\circ$ شمال الشرق","$30^\\circ$ شمال الشرق"]'::jsonb, 'تطبيق', 'حساب اتجاه سرعة نسبية من مثلث السرعات', 'متوسط', 'الكتاب ص 173 — المثال 3'),
('essay', 1, 'تريد طائرة صغيرة الوصول إلى مطار يقع على بعد $3.00\times10^{2}\ \text{km}$ شمالًا خلال 1.50 h، وتهب رياح من الشرق نحو الغرب بسرعة 30.0 km/h بالنسبة إلى الأرض.
(أ) ارسم مثلث السرعات المتجهة الثلاث.
(ب) احسب مقدار سرعة الطائرة بالنسبة إلى الهواء واتجاهها.', null, null, null, 'تحليل', 'مسألة ملاحة جوية برسم مثلث السرعات', 'متوسط', 'الكتاب ص 182 — السؤال 45'),
('essay', 2, 'يتجه قارب نحو الشمال الشرقي (بزاوية $45^\circ$ شمال الشرق) بسرعة 8.0 m/s بالنسبة إلى الماء، في نهر يجري ماؤه نحو الجنوب بسرعة 3.0 m/s بالنسبة إلى الضفة. ارسم متجهات السرعة بطريقة الرأس إلى الذيل، ثم احسب مقدار سرعة القارب بالنسبة إلى الضفة واتجاهها.', null, null, null, 'تطبيق', 'سرعة نسبية لسرعتين غير متعامدتين', 'صعب', 'الكتاب ص 175 — السؤال 23'),
('essay', 3, 'يبيّن الشكل الآتي، بمقياس رسم، سرعة طائرة بالنسبة إلى الهواء $1.80\times10^{2}\ \text{km/h}$ نحو الغرب، وسرعة الرياح بالنسبة إلى الأرض 60.0 km/h في اتجاه يصنع $45^\circ$ جنوب الغرب. احسب مقدار سرعة الطائرة بالنسبة إلى الأرض واتجاهها، موضحًا خطوات الحل بالمركبات.', null, '[{"src":"qimg/phys1/c6l3-o01-e3.svg","alt":"مخطط متجهات بمقياس رسم: من نقطة سوداء على اليمين سهم أحمر أفقي طويل نحو اليسار (الغرب) مكتوب فوقه v الطائرة بالنسبة إلى الهواء وتحته 1.80×10² km/h، ومن رأسه سهم أحمر قصير يميل إلى أسفل اليسار (الجنوب الغربي) مكتوب عنده 60.0 km/h وv الهواء بالنسبة إلى الأرض، وبينه وبين امتداد أفقي متقطع قوس زاوية مقدارها 45 درجة. في أسفل اليمين سهما الشمال (أعلى) والغرب (يسار)."}]'::jsonb, null, 'تطبيق', 'جمع سرعتين بالمركبات مع الرسم', 'متوسط', 'الكتاب ص 175 — السؤالان 24 و25')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L3-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, '$\boldsymbol{v}_{b/E} = \boldsymbol{v}_{b/w} + \boldsymbol{v}_{w/E}$، والمتجهان متعامدان فيكونان ضلعي مثلث قائم وترُه المحصلة: $v_{b/E} = \sqrt{(5.0)^2 + (2.0)^2} = 5.4\ \text{m/s}$.', '["","جُمع المقداران جمعًا جبريًّا ($5.0 + 2.0$)، وهذا لا يصح إلا إذا كانت السرعتان في الاتجاه نفسه، وهما متعامدتان.","طُرح المقداران ($5.0 - 2.0$) كأن السرعتين متعاكستان، وهما متعامدتان.","طُرح المربعان $\\sqrt{(5.0)^2 - (2.0)^2}$؛ والمحصلة هنا هي الوتر، فيُجمع المربعان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.280Z"}'::jsonb),
('mcq', 2, 2, 'السرعتان متعامدتان، والمحصلة تميل عن الشمال نحو الشرق بزاوية $\theta = \tan^{-1}\left(\frac{45}{150}\right) = 17^\circ$، أي $17^\circ$ شرق الشمال.', '["قُسمت السرعتان مقلوبتين ($\\tan^{-1}\\frac{150}{45}$)؛ وهذه الزاوية تُقاس من الشرق لا من الشمال.","الرياح تهب نحو الشرق فتحرف الطائرة نحو الشرق لا نحو الغرب.","","اجتمع خطآن: قُلبت النسبة فقيست الزاوية من الشرق، وعُكس جانب الانحراف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-21T13:36:33.281Z"}'::jsonb),
('mcq', 3, 3, 'السرعة المطلوبة بالنسبة إلى الأرض $\frac{3.60\times10^{2}\ \text{km}}{2.00\ \text{h}} = 180\ \text{km/h}$ جنوبًا. وسرعة الطائرة بالنسبة إلى الهواء = سرعتها بالنسبة إلى الأرض − سرعة الهواء بالنسبة إلى الأرض، أي مجموع 180 km/h جنوبًا و40.0 km/h غربًا، وهما متعامدان: $\sqrt{(180)^2 + (40.0)^2} = 184\ \text{km/h}$ (في اتجاه يميل غرب الجنوب).', '["طُرح المربعان $\\sqrt{180^2 - 40.0^2} = 175\\ \\text{km/h}$؛ لكن سرعة الطائرة بالنسبة إلى الهواء هنا هي الوتر لأن المطلوب أن تكون محصلتها مع الرياح 180 km/h جنوبًا.","جُمع المقداران كأن الرياح معاكسة لاتجاه الطيران، وهي عمودية عليه.","طُرح المقداران كأن الرياح في اتجاه الطيران، وهي عمودية عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-21T13:36:33.282Z"}'::jsonb),
('mcq', 4, 1, 'المحصلة $\boldsymbol{v}_{b/E} = \boldsymbol{v}_{b/w} + \boldsymbol{v}_{w/E}$ تمتد من ذيل المتجه الأول إلى رأس الثاني. مركبتاها من الشبكة: $x = 2.0 + 3.0 = 5.0\ \text{m/s}$ و$y = 4.0\ \text{m/s}$، فمقدارها $\sqrt{(5.0)^2 + (4.0)^2} = 6.4\ \text{m/s}$.', '["جُمع مقدارا المتجهين ($4.5 + 3.0$) جمعًا جبريًّا، وهما غير متوازيين.","","جُمعت مركبتا المحصلة ($5.0 + 4.0$) جبريًّا بدل استعمال نظرية فيثاغورس.","هذا مقدار سرعة القارب بالنسبة إلى الماء وحدها؛ أُهمل أثر التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.282Z"}'::jsonb),
('mcq', 5, 2, 'المحصلة (سرعة القارب بالنسبة إلى الضفة) عمودية على التيار، وسرعة القارب بالنسبة إلى الماء هي وتر المثلث القائم: $v_{b/E} = \sqrt{(5.0)^2 - (2.5)^2} = 4.3\ \text{m/s}$.', '["عُدّت سرعة القارب بالنسبة إلى الماء ضلعًا قائمًا وجُمع المربعان، مع أنها الوتر لأن القارب موجّه بزاوية عكس التيار.","طُرح المقداران جبريًّا ($5.0 - 2.5$) كأن الحركة في خط واحد.","","جُمع المقداران جبريًّا، والسرعتان ليستا في الاتجاه نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.283Z"}'::jsonb),
('mcq', 6, 3, 'تُحلَّل سرعة الرياح إلى مركبتين ثم تُجمع المركبات: $v_x = 220 + 50.0\cos 45^\circ = 255.4\ \text{km/h}$، و$v_y = 50.0\sin 45^\circ = 35.4\ \text{km/h}$، فالمقدار $\sqrt{(255.4)^2 + (35.4)^2} = 258\ \text{km/h}$.', '["جُمع المقداران جبريًّا، وهذا لا يصح إلا إذا كانت الرياح في اتجاه الطائرة تمامًا.","استُعملت نظرية فيثاغورس مباشرة كأن السرعتين متعامدتان، والزاوية بينهما $45^\\circ$.","طُرح المقداران كأن الرياح معاكسة للطائرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (61%)"}],"at":"2026-11-21T13:36:33.283Z"}'::jsonb),
('mcq', 7, 0, '$\boldsymbol{v}_{m/w} = \boldsymbol{v}_{m/b} + \boldsymbol{v}_{b/w}$، والسرعتان متعامدتان، فالزاوية مع الشرق $\theta = \tan^{-1}\left(\frac{v_{m/b}}{v_{b/w}}\right) = \tan^{-1}\left(\frac{1.5}{3.0}\right) = 27^\circ$ شمال الشرق.', '["","قُلبت النسبة ($\\tan^{-1}\\frac{3.0}{1.5}$)؛ وهذه الزاوية مقيسة من الشمال لا من الشرق.","استُعمل معكوس جيب التمام ($\\cos^{-1}\\frac{1.5}{3.0}$) بقسمة غير صحيحة للضلعين.","استُعمل معكوس الجيب ($\\sin^{-1}\\frac{1.5}{3.0}$) مع أن 3.0 m/s ضلع مجاور لا وتر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.284Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السرعة المطلوبة بالنسبة إلى الأرض $\frac{3.00\times10^{2}\ \text{km}}{1.50\ \text{h}} = 200\ \text{km/h}$ شمالًا. سرعة الطائرة بالنسبة إلى الأرض = سرعتها بالنسبة إلى الهواء + سرعة الهواء بالنسبة إلى الأرض؛ فسرعتها بالنسبة إلى الهواء = 200 km/h شمالًا − 30.0 km/h غربًا = 200 km/h شمالًا + 30.0 km/h شرقًا. في المثلث: سهم سرعة الطائرة بالنسبة إلى الهواء يميل شرق الشمال، ومن رأسه سهم الرياح نحو الغرب، والمحصلة من ذيل الأول إلى رأس الثاني نحو الشمال تمامًا. المقدار $\sqrt{(200)^2 + (30.0)^2} = 202\ \text{km/h}$، والاتجاه $\theta = \tan^{-1}\left(\frac{30.0}{200}\right) = 8.5^\circ$ شرق الشمال؛ أي توجَّه الطائرة قليلًا نحو الشرق لتعوّض انجرافها مع الرياح نحو الغرب.', '["حساب السرعة المطلوبة بالنسبة إلى الأرض 200 km/h شمالًا","مثلث سرعات صحيح تكون فيه المحصلة نحو الشمال","المقدار 202 km/h","الاتجاه $8.5^\\circ$ شرق الشمال"]'::jsonb, '["$v = \\frac{\\Delta d}{\\Delta t} = \\frac{3.00\\times10^{2}\\ \\text{km}}{1.50\\ \\text{h}} = 200\\ \\text{km/h}$ شمالًا","سرعة الطائرة بالنسبة إلى الهواء = سرعتها بالنسبة إلى الأرض − سرعة الهواء بالنسبة إلى الأرض","المقدار $= \\sqrt{(200)^2 + (30.0)^2} = 202\\ \\text{km/h}$","$\\theta = \\tan^{-1}(30.0/200) = 8.5^\\circ$ شرق الشمال"]'::jsonb, '[{"element":"السرعة المطلوبة بالنسبة إلى الأرض","marks":1},{"element":"رسم المثلث","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب السرعة المطلوبة ورسم صحيح وحساب المقدار والاتجاه"},{"level":"2–3 درجات","description":"أخطأ في الاتجاه أو في الرسم مع صحة بقية الخطوات"},{"level":"درجة واحدة","description":"حسب السرعة المطلوبة بالنسبة إلى الأرض فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توجيه الطائرة غرب الشمال (مع الرياح) بدل شرقه","جمع 200 و30.0 جبريًّا","عدّ 200 km/h سرعة الطائرة بالنسبة إلى الهواء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-21T13:36:33.285Z"}'::jsonb),
('essay', 2, null::int, null, null, '$\boldsymbol{v}_{b/E} = \boldsymbol{v}_{b/w} + \boldsymbol{v}_{w/E}$. نحلل سرعة القارب بالنسبة إلى الماء: $v_x = 8.0\cos 45^\circ = 5.66\ \text{m/s}$ شرقًا، و$v_y = 8.0\sin 45^\circ = 5.66\ \text{m/s}$ شمالًا. سرعة الماء نحو الجنوب فتُطرح من المركبة الشمالية: $v_y = 5.66 - 3.0 = 2.66\ \text{m/s}$. المقدار $\sqrt{(5.66)^2 + (2.66)^2} = 6.2\ \text{m/s}$، والاتجاه $\tan^{-1}\left(\frac{2.66}{5.66}\right) = 25^\circ$ شمال الشرق. في الرسم: سهم $\boldsymbol{v}_{b/w}$ بزاوية $45^\circ$، ومن رأسه سهم $\boldsymbol{v}_{w/E}$ إلى الأسفل، والمحصلة من ذيل الأول إلى رأس الثاني.', '["رسم صحيح بطريقة الرأس إلى الذيل","تحليل سرعة القارب إلى مركبتين","طرح سرعة التيار من المركبة الشمالية","المقدار 6.2 m/s والاتجاه $25^\\circ$ شمال الشرق"]'::jsonb, '["$v_x = 8.0\\cos 45^\\circ = 5.66\\ \\text{m/s}$","$v_y = 8.0\\sin 45^\\circ - 3.0 = 2.66\\ \\text{m/s}$","$v_{b/E} = \\sqrt{(5.66)^2 + (2.66)^2} = 6.2\\ \\text{m/s}$","$\\theta = \\tan^{-1}(2.66/5.66) = 25^\\circ$ شمال الشرق"]'::jsonb, '[{"element":"الرسم","marks":1},{"element":"المركبات","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم صحيح ومركبات صحيحة ومقدار واتجاه صحيحان"},{"level":"2–3 درجات","description":"خطأ في إشارة مركبة التيار أو في الاتجاه مع صحة الطريقة"},{"level":"درجة واحدة","description":"رسم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع سرعة التيار مع المركبة الشمالية بدل طرحها","استعمال نظرية فيثاغورس مباشرة على 8.0 و3.0","جمع 8.0 و3.0 جبريًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-21T13:36:33.285Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نختار +x نحو الشرق و+y نحو الشمال. مركبتا سرعة الطائرة بالنسبة إلى الهواء: $(-180,\ 0)$. مركبتا الرياح: $-60.0\cos 45^\circ = -42.4$ و$-60.0\sin 45^\circ = -42.4\ \text{km/h}$. المجموع: $v_x = -222.4\ \text{km/h}$ و$v_y = -42.4\ \text{km/h}$. المقدار $\sqrt{(222.4)^2 + (42.4)^2} = 226\ \text{km/h}$، والاتجاه $\tan^{-1}\left(\frac{42.4}{222.4}\right) = 10.8^\circ$ جنوب الغرب.', '["تحليل سرعة الرياح إلى مركبتين بإشارتين صحيحتين","جمع المركبات","المقدار 226 km/h","الاتجاه $10.8^\\circ$ جنوب الغرب"]'::jsonb, '["مركبتا الرياح: $-42.4$ و$-42.4\\ \\text{km/h}$","$v_x = -180 - 42.4 = -222.4\\ \\text{km/h}$، $v_y = -42.4\\ \\text{km/h}$","$v = \\sqrt{(222.4)^2 + (42.4)^2} = 226\\ \\text{km/h}$","$\\theta = \\tan^{-1}(42.4/222.4) = 10.8^\\circ$ جنوب الغرب"]'::jsonb, '[{"element":"مركبتا الرياح","marks":1},{"element":"جمع المركبات","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مركبات وإشارات صحيحة ومقدار واتجاه صحيحان"},{"level":"2–3 درجات","description":"خطأ في إحدى الإشارات أو في الاتجاه"},{"level":"درجة واحدة","description":"تحليل صحيح للرياح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع 180 و60.0 جبريًّا","استعمال فيثاغورس على 180 و60.0 كأنهما متعامدتان","قياس الزاوية من الجنوب بدل الغرب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (61%)"}],"at":"2026-11-21T13:36:33.286Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L3-O01') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L3-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يجلس راكب في مقعده داخل قطار يتحرك بسرعة 20 m/s نحو الشرق بالنسبة إلى الأرض. أيّ العبارات الآتية تصف سرعته المتجهة وصفًا صحيحًا؟', null, null, '["سرعته صفر بالنسبة إلى القطار وصفر كذلك بالنسبة إلى الأرض","سرعته 20 m/s بالنسبة إلى القطار وصفر بالنسبة إلى الأرض","سرعته صفر بالنسبة إلى القطار و20 m/s شرقًا بالنسبة إلى الأرض","سرعته 20 m/s شرقًا بالنسبة إلى القطار وبالنسبة إلى الأرض معًا"]'::jsonb, 'فهم', 'تفسير مفهوم السرعة النسبية', 'سهل', 'الكتاب ص 172 — مقدمة الدرس (القطار)'),
('mcq', 2, 'يتحرك قارب نحو الشرق بالنسبة إلى الماء، ودُحرجت كرة على سطحه نحو الشمال بالنسبة إلى القارب، حيث يرمز m للكرة، وb للقارب، وw للماء. أيّ المخططات المرقّمة في الشكل الآتي يمثّل العلاقة $\boldsymbol{v}_{m/w} = \boldsymbol{v}_{m/b} + \boldsymbol{v}_{b/w}$ تمثيلًا صحيحًا؟', null, '[{"src":"qimg/phys1/c6l3-o02-panels.svg","alt":"أربعة مخططات مرقمة من (1) إلى (4)، في كل منها ثلاثة أسهم حمراء تشكل مثلثًا قائمًا. (1): v b/w أفقي إلى اليمين، ومن رأسه v m/b إلى أعلى، وv m/w من ذيل v b/w إلى رأس v m/b. (2): مثل (1) لكن v m/w يتجه من رأس v m/b عائدًا إلى ذيل v b/w. (3): v b/w إلى اليمين وv m/b إلى أعلى يبدآن من النقطة نفسها، وv m/w من رأس v m/b إلى رأس v b/w. (4): v b/w إلى اليمين، ومن رأسه v m/b إلى أسفل، وv m/w من ذيل v b/w إلى رأس v m/b."}]'::jsonb, '["المخطط (2)","المخطط (3)","المخطط (4)","المخطط (1)"]'::jsonb, 'تطبيق', 'تمييز مثلث السرعات الصحيح', 'متوسط', 'الكتاب ص 173–174 — المثال 3 ومثلث السرعات'),
('mcq', 3, 'يبيّن الشكل الآتي مثلث السرعات المتجهة لطائرة تهب عليها رياح. ماذا يمثل الضلع المتقطع المشار إليه بعلامة الاستفهام؟', null, '[{"src":"qimg/phys1/c6l3-o02-triangle.svg","alt":"مثلث من أسهم حمراء: سهم رأسي إلى أعلى مكتوب بجانبه v الطائرة بالنسبة إلى الهواء، ومن رأسه سهم يميل إلى أسفل اليمين مكتوب عنده v الهواء بالنسبة إلى الأرض، وضلع ثالث متقطع برأس سهم يمتد من ذيل السهم الرأسي إلى رأس السهم المائل، وعنده علامة استفهام. في أسفل اليمين سهما الشمال والشرق."}]'::jsonb, '["سرعة الطائرة المتجهة بالنسبة إلى الأرض","سرعة الهواء المتجهة بالنسبة إلى الطائرة","سرعة الطائرة المتجهة بالنسبة إلى الهواء","سرعة الأرض المتجهة بالنسبة إلى الهواء"]'::jsonb, 'فهم', 'تفسير مثلث السرعات', 'سهل', 'الكتاب ص 173 — الشكل 6-10'),
('mcq', 4, 'لماذا لا يكفي أن يوجّه الملاح الجوي مقدمة طائرته نحو المطار المقصود ليصل إليه عندما تهب رياح جانبية؟', null, null, '["لأن الرياح تغيّر مقدار سرعة الطائرة بالنسبة إلى الهواء ولا تغيّر اتجاه حركتها","لأن سرعتها بالنسبة إلى الأرض هي الجمع الاتجاهي لسرعتها بالنسبة إلى الهواء وسرعة الهواء","لأن سرعة الطائرة بالنسبة إلى الأرض تساوي دائمًا سرعتها بالنسبة إلى الهواء مقدارًا واتجاهًا","لأن البوصلة في الطائرة تعطي قراءات غير صحيحة عند الطيران على ارتفاعات عالية"]'::jsonb, 'فهم', 'تفسير الحاجة إلى الجمع الاتجاهي', 'متوسط', 'الكتاب ص 173 — الملاحون الجويون'),
('mcq', 5, 'يقذف راكب كرة رأسيًّا إلى أعلى بالنسبة إليه داخل قطار يتحرك بسرعة متجهة ثابتة على سكة أفقية. كيف يكون اتجاه سرعة الكرة لحظة قذفها بالنسبة إلى راصد ساكن على الأرض؟', null, null, '["رأسيًّا إلى أعلى كما يراها الراكب تمامًا","مائلًا إلى أعلى نحو اتجاه حركة القطار","أفقيًّا في اتجاه حركة القطار فقط","مائلًا إلى أعلى عكس اتجاه حركة القطار"]'::jsonb, 'تطبيق', 'تطبيق مفهوم السرعة النسبية في موقف جديد', 'صعب', 'الكتاب ص 172، 180 — الدرس والسؤال 36'),
('mcq', 6, 'يبيّن الشكل الآتي سرعة قارب بالنسبة إلى الماء $\boldsymbol{v}_{b/w}$ عمودية على الضفة، وسرعة الماء بالنسبة إلى الضفة $\boldsymbol{v}_{w/E}$. كيف يبدو مسار القارب لراصد يقف على الضفة؟', null, '[{"src":"qimg/phys1/c6l3-o02-river.svg","alt":"نهر بين ضفتين خضراوين أفقيتين، وفيه قارب. من القارب سهم أحمر إلى أعلى عمودي على الضفة مكتوب عنده v b/w، وسهم أحمر أقصر إلى اليمين موازٍ للضفة مكتوب عنده v w/E. في أعلى اليمين سهم رمادي إلى اليمين مكتوب تحته اتجاه التيار."}]'::jsonb, '["مائلًا نحو اتجاه جريان التيار","عموديًّا على الضفة تمامًا","مائلًا عكس اتجاه جريان التيار","موازيًا للضفة في اتجاه التيار"]'::jsonb, 'فهم', 'تفسير مسار جسم في إطار مرجعي متحرك', 'سهل', 'الكتاب ص 182 — السؤال 46'),
('mcq', 7, 'يمشي راكب نحو مؤخرة قطار كما في الشكل الآتي، حيث يرمز y للراكب، وt للقطار، وE للأرض. أيّ العبارات الآتية تفسّر بصورة صحيحة سرعة الراكب بالنسبة إلى راصد ساكن على الأرض؟', null, '[{"src":"qimg/phys1/c6l3-o02-train.svg","alt":"قطار مرسوم مستطيلًا على سكة أفقية، وفوقه نقطة تمثل الراكب. في الأعلى سهم أحمر طويل إلى اليمين مكتوب فوقه v t/E وبجانبه 20 m/s، وتحته فوق الراكب سهم أحمر قصير إلى اليسار مكتوب فوقه v y/t وبجانبه 2.0 m/s. في أسفل اليمين سهم يدل على +x إلى اليمين."}]'::jsonb, '["تساوي سرعة القطار؛ لأن الراكب موجود داخل القطار","أكبر من سرعة القطار؛ لأن السرعتين تُجمعان دائمًا جمعًا جبريًّا","أصغر من سرعة القطار؛ لأن المتجهين متعاكسان فيُطرح مقداراهما","تساوي سرعة الراكب بالنسبة إلى القطار؛ لأن الراصد يرى الراكب فقط"]'::jsonb, 'فهم', 'تفسير الجمع الاتجاهي لسرعتين متعاكستين', 'متوسط', 'الكتاب ص 172 — الشكل 6-9b'),
('essay', 1, 'يجلس راكب في قطار يتحرك بسرعة 25.0 m/s نحو الشرق بالنسبة إلى الأرض، ثم يمشي داخل القطار بسرعة 1.5 m/s نحو مقدمته، ثم نحو مؤخرته. وضّح باستعمال رسم متجهات السرعة المقصودَ بالسرعة المتجهة النسبية، وحدّد سرعة الراكب بالنسبة إلى الأرض في الحالات الثلاث.', null, null, null, 'فهم', 'توضيح مفهوم بالرسم', 'متوسط', 'الكتاب ص 172 — الشكل 6-9'),
('essay', 2, 'وضّح، مستعينًا برسم مثلث السرعات المتجهة الثلاث، لماذا يختلف اتجاه مقدمة طائرة عن اتجاه مسارها الفعلي فوق الأرض عندما تهب رياح جانبية، وكيف يختار الملاح اتجاه مقدمة الطائرة ليصل إلى وجهته.', null, null, null, 'فهم', 'توضيح مفهوم بالرسم', 'صعب', 'الكتاب ص 173 — الشكل 6-10'),
('essay', 3, 'يجلس أحمد على قارب يتحرك نحو الشرق بالنسبة إلى الماء، ويدحرج كرة نحو جمال في عرض القارب نحو الشمال، بينما يراقب سعيد الكرة من الضفة (الماء ساكن). يقول أحمد إن الكرة تتحرك نحو الشمال، ويقول سعيد إنها تتحرك في اتجاه بين الشمال والشرق. وضّح برسم متجهات السرعة سبب الاختلاف، وبيّن أيّهما على صواب.', null, null, null, 'فهم', 'توضيح مفهوم بالرسم', 'صعب', 'الكتاب ص 173 — المثال 3')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L3-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'السرعة المتجهة تُقاس بالنسبة إلى إطار مرجعي. الراكب لا يتحرك بالنسبة إلى القطار فسرعته بالنسبة إليه صفر، وسرعته بالنسبة إلى الأرض = صفر + سرعة القطار = 20 m/s شرقًا.', '["الراكب ساكن بالنسبة إلى القطار فقط؛ أما بالنسبة إلى الأرض فيتحرك مع القطار.","عُكس الإطاران المرجعيان؛ فهو لا يتحرك داخل القطار.","","سرعته بالنسبة إلى القطار صفر لأنه لا يتحرك داخله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.287Z"}'::jsonb),
('mcq', 2, 3, 'في الجمع الاتجاهي يُرسم المتجه الثاني من رأس الأول (الرأس إلى الذيل)، والمحصلة $\boldsymbol{v}_{m/w}$ من ذيل الأول إلى رأس الأخير. المخطط (1) يحقق ذلك: $\boldsymbol{v}_{b/w}$ شرقًا، ثم $\boldsymbol{v}_{m/b}$ شمالًا من رأسه، والمحصلة من نقطة البداية إلى النهاية.', '["اتجاه المحصلة معكوس؛ والصحيح أن تبدأ من ذيل المتجه الأول وتنتهي عند رأس المتجه الأخير.","رُسم المتجهان من نقطة واحدة (ذيلًا إلى ذيل)، والضلع الواصل بين رأسيهما يمثل الفرق بينهما لا مجموعهما.","رُسم $\\boldsymbol{v}_{m/b}$ نحو الجنوب، والكرة تتحرك نحو الشمال بالنسبة إلى القارب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.287Z"}'::jsonb),
('mcq', 3, 0, 'الضلع المتقطع يبدأ من ذيل سرعة الطائرة بالنسبة إلى الهواء وينتهي عند رأس سرعة الهواء بالنسبة إلى الأرض، فهو حاصل جمعهما الاتجاهي: سرعة الطائرة بالنسبة إلى الأرض.', '["","سرعة الهواء بالنسبة إلى الطائرة تعاكس سرعة الطائرة بالنسبة إلى الهواء، وليست الضلع الثالث.","هذه السرعة يمثلها الضلع الرأسي المرسوم أولًا لا الضلع المتقطع.","هذه تعاكس سرعة الهواء بالنسبة إلى الأرض، ولا تمثل المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.287Z"}'::jsonb),
('mcq', 4, 1, 'الطائرة تتحرك بالنسبة إلى الهواء، والهواء نفسه يتحرك بالنسبة إلى الأرض؛ فسرعتها بالنسبة إلى الأرض حاصل الجمع الاتجاهي للسرعتين، والرياح الجانبية تحرفها عن اتجاه مقدمتها، لذا يجب أخذ سرعة الرياح واتجاهها في الحسبان.', '["الرياح لا تغيّر سرعة الطائرة بالنسبة إلى الهواء، بل تغيّر سرعتها بالنسبة إلى الأرض مقدارًا واتجاهًا.","","لو صح ذلك لوصلت الطائرة بتوجيهها نحو المطار؛ والسرعتان تختلفان بوجود الرياح.","المشكلة ليست في البوصلة بل في حركة الهواء نفسه بالنسبة إلى الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.288Z"}'::jsonb),
('mcq', 5, 1, 'سرعة الكرة بالنسبة إلى الأرض = سرعتها بالنسبة إلى القطار (رأسية إلى أعلى) + سرعة القطار بالنسبة إلى الأرض (أفقية). مجموع متجه رأسي ومتجه أفقي متجه مائل إلى أعلى نحو اتجاه حركة القطار.', '["هذا وصفها في إطار القطار؛ أما الراصد على الأرض فيضيف سرعة القطار إليها.","","أُهملت السرعة الرأسية التي أُعطيت للكرة.","سرعة القطار تُجمع مع سرعة الكرة، فيميل المجموع نحو اتجاه حركة القطار لا عكسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.288Z"}'::jsonb),
('mcq', 6, 0, '$\boldsymbol{v}_{b/E} = \boldsymbol{v}_{b/w} + \boldsymbol{v}_{w/E}$: مجموع سرعة عمودية على الضفة وسرعة موازية لها متجه مائل نحو اتجاه التيار، فيعبر القارب النهر وينجرف معه.', '["","هذا مسار القارب بالنسبة إلى الماء؛ أما بالنسبة إلى الضفة فيُضاف إليه أثر التيار.","التيار يحمل القارب في اتجاه جريانه لا عكسه.","أُهملت سرعة القارب العمودية على الضفة، فهو يعبر النهر أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.289Z"}'::jsonb),
('mcq', 7, 2, '$\boldsymbol{v}_{y/E} = \boldsymbol{v}_{y/t} + \boldsymbol{v}_{t/E}$، والمتجهان في الشكل متعاكسان، فمقدار المحصلة يساوي الفرق بين المقدارين، أي أصغر من سرعة القطار وفي اتجاه حركته.', '["هذا صحيح للراكب الجالس فقط؛ والراكب هنا يتحرك بالنسبة إلى القطار.","الجمع اتجاهي؛ والمتجهان هنا متعاكسان فيكون المقدار الناتج أصغر.","","الراصد على الأرض يقيس حركة الراكب مع القطار معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.289Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السرعة المتجهة النسبية هي سرعة الجسم مقيسة بالنسبة إلى إطار مرجعي معيّن، وتختلف باختلاف هذا الإطار. حالة الجلوس: سرعة الراكب بالنسبة إلى القطار صفر، وبالنسبة إلى الأرض 25.0 m/s شرقًا (سهم واحد هو سرعة القطار). حالة المشي نحو المقدمة: يُرسم سهم سرعة القطار شرقًا، ومن رأسه سهم 1.5 m/s شرقًا، فالمحصلة سهم أطول: $25.0 + 1.5 = 26.5\ \text{m/s}$ شرقًا. حالة المشي نحو المؤخرة: من رأس سهم القطار سهم 1.5 m/s غربًا، فالمحصلة أقصر: $25.0 - 1.5 = 23.5\ \text{m/s}$ شرقًا. فسرعة الراكب بالنسبة إلى الأرض هي حاصل الجمع الاتجاهي لسرعته بالنسبة إلى القطار وسرعة القطار بالنسبة إلى الأرض.', '["تعريف السرعة النسبية بدلالة الإطار المرجعي","رسم المتجهات في الحالات الثلاث","الجلوس: صفر بالنسبة إلى القطار و25.0 m/s بالنسبة إلى الأرض","26.5 m/s و23.5 m/s شرقًا"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الرسوم","marks":1},{"element":"حالة الجلوس","marks":1},{"element":"حالتا المشي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ورسوم صحيحة ونتائج الحالات الثلاث صحيحة"},{"level":"2–3 درجات","description":"رسوم أو نتائج ناقصة لحالة واحدة"},{"level":"درجة واحدة","description":"تعريف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الراكب الجالس سرعته صفر مطلقًا","جمع المقدارين في حالة المشي نحو المؤخرة","رسم المتجهين دون الرأس إلى الذيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.290Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مقدمة الطائرة تشير إلى اتجاه سرعتها بالنسبة إلى الهواء، أما مسارها فوق الأرض فيتبع سرعتها بالنسبة إلى الأرض. في المثلث يُرسم سهم سرعة الطائرة بالنسبة إلى الهواء، ومن رأسه سهم سرعة الهواء بالنسبة إلى الأرض، والضلع الثالث من ذيل الأول إلى رأس الثاني هو سرعة الطائرة بالنسبة إلى الأرض. ولأن الرياح جانبية يميل الضلع الثالث عن السهم الأول، فيختلف المسار عن اتجاه المقدمة. ليصل الملاح إلى وجهته يجعل الضلع الثالث (المحصلة) متجهًا نحو الوجهة، فيوجّه المقدمة بزاوية نحو الجهة التي تهب منها الرياح، بحيث تلغي مركبة سرعة الطائرة العمودية على المسار أثرَ الرياح.', '["المقدمة تحدد السرعة بالنسبة إلى الهواء","رسم المثلث صحيحًا","المحصلة هي السرعة بالنسبة إلى الأرض وتختلف في الاتجاه","توجيه المقدمة نحو مصدر الرياح لتكون المحصلة نحو الوجهة"]'::jsonb, '[]'::jsonb, '[{"element":"دلالة اتجاه المقدمة","marks":1},{"element":"الرسم","marks":1},{"element":"تفسير الاختلاف","marks":1},{"element":"طريقة اختيار الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع رسم صحيح وطريقة توجيه صحيحة"},{"level":"2–3 درجات","description":"تفسير صحيح مع رسم ناقص أو طريقة توجيه غير دقيقة"},{"level":"درجة واحدة","description":"ذكر أن الرياح تحرف الطائرة دون رسم أو تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توجيه المقدمة مع اتجاه الرياح","عدّ اتجاه المقدمة هو اتجاه المسار","رسم المتجهات ذيلًا إلى ذيل وأخذ الضلع الواصل بين الرأسين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.290Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كلاهما على صواب؛ لأن كل واحد يقيس السرعة بالنسبة إلى إطار مرجعي مختلف. أحمد يتحرك مع القارب فيقيس سرعة الكرة بالنسبة إلى القارب، وهي نحو الشمال. أما سعيد فيقيس سرعة الكرة بالنسبة إلى الماء (والضفة)، وهي: سرعة الكرة بالنسبة إلى القارب + سرعة القارب بالنسبة إلى الماء. في الرسم: سهم سرعة القارب نحو الشرق، ومن رأسه سهم سرعة الكرة بالنسبة إلى القارب نحو الشمال، والمحصلة من ذيل الأول إلى رأس الثاني تميل شمال الشرق، ومقدارها أكبر من كل من السرعتين.', '["كلاهما صحيح لاختلاف الإطار المرجعي","أحمد يقيس السرعة بالنسبة إلى القارب","سعيد يقيس المجموع الاتجاهي للسرعتين","رسم صحيح للمثلث بمحصلة تميل شمال الشرق"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع التعليل","marks":1},{"element":"إطار أحمد","marks":1},{"element":"إطار سعيد","marks":1},{"element":"الرسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتفسير الإطارين ورسم صحيح"},{"level":"2–3 درجات","description":"حكم صحيح مع تفسير أو رسم ناقص"},{"level":"درجة واحدة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تخطئة أحد الراصدين","جمع المقدارين جمعًا جبريًّا","رسم المحصلة نحو الشمال الغربي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.290Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
