('mcq', 4, 'يدحرج راكب كرة على سطح قارب متحرك في الماء، حيث يرمز m للكرة، وb للقارب، وw للماء. أيّ المعادلات الآتية تعطي سرعة الكرة بالنسبة إلى الماء؟', null, null, '["$\\boldsymbol{v}_{m/w} = \\boldsymbol{v}_{m/b} + \\boldsymbol{v}_{w/b}$","$\\boldsymbol{v}_{m/w} = \\boldsymbol{v}_{m/b} + \\boldsymbol{v}_{b/w}$","$\\boldsymbol{v}_{m/w} = \\boldsymbol{v}_{b/m} + \\boldsymbol{v}_{b/w}$","$\\boldsymbol{v}_{m/w} = \\boldsymbol{v}_{m/b} - \\boldsymbol{v}_{b/w}$"]'::jsonb, 'تطبيق', 'كتابة المعادلة لموقف معيّن', 'متوسط', 'الكتاب ص 173 — المثال 3'),
('mcq', 5, 'ما العلاقة بين $\boldsymbol{v}_{b/c}$ و$\boldsymbol{v}_{c/b}$؟', null, null, '["متساويتان مقدارًا ومتعاكستان اتجاهًا","متساويتان مقدارًا ومتفقتان اتجاهًا","متعامدتان ولهما المقدار نفسه دائمًا","مقدار إحداهما ضعف مقدار الأخرى دائمًا"]'::jsonb, 'فهم', 'تفسير دلالة ترتيب الرموز', 'متوسط', 'الكتاب ص 172 — السرعة المتجهة النسبية'),
('mcq', 6, 'يريد طالب أن يحسب $\boldsymbol{v}_{x/z}$ بمعادلة السرعة المتجهة النسبية، ويعرف $\boldsymbol{v}_{x/y}$. ما السرعة الأخرى التي يجب أن يعرفها؟', null, null, '["$\\boldsymbol{v}_{y/x}$","$\\boldsymbol{v}_{z/y}$","$\\boldsymbol{v}_{x/z}$","$\\boldsymbol{v}_{y/z}$"]'::jsonb, 'فهم', 'تفسير بنية المعادلة', 'صعب', 'الكتاب ص 172 — السرعة المتجهة النسبية'),
('mcq', 7, 'متى يكون المقدار $v_{a/c}$ مساويًا لمجموع المقدارين $v_{a/b} + v_{b/c}$؟', null, null, '["في جميع الحالات، لأن المعادلة تجمع السرعتين","عندما تكون السرعتان متعامدتين","عندما تكون السرعتان في الاتجاه نفسه","عندما تكون السرعتان متعاكستين"]'::jsonb, 'فهم', 'تفسير المعادلة بوصفها جمعًا اتجاهيًّا', 'صعب', 'الكتاب ص 172، 174 — الجمع والطرح ومثلث السرعات'),
('essay', 1, 'اكتب معادلة السرعة المتجهة النسبية، ووضّح دلالة كل رمز فيها، ثم عبّر عنها بالكلمات.', null, null, null, 'فهم', 'كتابة معادلة وتفسير رموزها', 'سهل', 'الكتاب ص 172، 179 — السرعة المتجهة النسبية'),
('essay', 2, 'ابدأ من المعادلة $\boldsymbol{v}_{m/w} = \boldsymbol{v}_{m/b} + \boldsymbol{v}_{b/w}$ (m للكرة، b للقارب، w للماء).
(أ) أعد ترتيبها لإيجاد سرعة الكرة بالنسبة إلى القارب.
(ب) فسّر لماذا $\boldsymbol{v}_{w/b} = -\boldsymbol{v}_{b/w}$.
(ج) إذا كانت، في خط مستقيم واحد واتجاه الشرق موجبًا، $v_{m/w} = +4.3\ \text{m/s}$ و$v_{b/w} = +3.5\ \text{m/s}$، فاحسب $v_{m/b}$ وفسّر معناه.', null, null, null, 'فهم', 'إعادة ترتيب المعادلة وتفسير رموزها', 'متوسط', 'الكتاب ص 172–173 — المعادلة والمثال 3'),
('essay', 3, 'كتب طالب لراكب يمشي نحو مقدمة قطار المعادلة $\boldsymbol{v}_{y/E} = \boldsymbol{v}_{t/E} + \boldsymbol{v}_{t/y}$ (y للراكب، t للقطار، E للأرض). قوّم هذه المعادلة، واكتب الصحيحة، ثم احسب بالمعادلتين سرعة الراكب بالنسبة إلى الأرض إذا كانت سرعة القطار 15.0 m/s وسرعة الراكب بالنسبة إلى القطار 2.0 m/s نحو المقدمة (اتجاه الحركة موجب)، وبيّن أيّ النتيجتين منطقية.', null, null, null, 'تقويم', 'تقويم معادلة وتصحيحها', 'صعب', 'الكتاب ص 172، 174 — المعادلة والمسألة 19')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L3-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'سرعة الجسم a بالنسبة إلى الجسم c هي حاصل الجمع الاتجاهي لسرعة a بالنسبة إلى b وسرعة b بالنسبة إلى c: $\boldsymbol{v}_{a/c} = \boldsymbol{v}_{a/b} + \boldsymbol{v}_{b/c}$.', '["المعادلة جمع اتجاهي للسرعتين لا طرح.","","رُتّب الحرفان في الحد الثاني ترتيبًا معكوسًا؛ و$\\boldsymbol{v}_{c/b}$ يعاكس $\\boldsymbol{v}_{b/c}$.","عُكس ترتيب الحروف في الحدين، فصار كل منهما معاكسًا للمطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-21T13:36:33.291Z"}'::jsonb),
('mcq', 2, 0, 'الحرف الأول في الرمز السفلي هو الجسم الذي تُقاس سرعته، والحرف بعد الخط المائل هو الجسم الذي تُقاس بالنسبة إليه؛ فـ$\boldsymbol{v}_{a/b}$ سرعة a بالنسبة إلى b.', '["","الخط المائل في الرمز يعني «بالنسبة إلى» لا القسمة.","الرمز يدل على سرعة جسم واحد بالنسبة إلى جسم آخر، لا على مجموع سرعتين.","عُكس الترتيب؛ فالحرف الأول هو الجسم المتحرك والثاني هو الإطار المرجعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-21T13:36:33.292Z"}'::jsonb),
('mcq', 3, 2, 'الجسم المتحرك هو الراكب (y) والإطار المرجعي هو القطار (t)، فالرمز $\boldsymbol{v}_{y/t}$.', '["هذا سرعة القطار بالنسبة إلى الأرض.","هذا سرعة الراكب بالنسبة إلى الأرض، وهو المحصلة.","","هذا سرعة القطار بالنسبة إلى الراكب، وهي تعاكس سرعة الراكب بالنسبة إلى القطار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.292Z"}'::jsonb),
('mcq', 4, 1, 'بتطبيق $\boldsymbol{v}_{a/c} = \boldsymbol{v}_{a/b} + \boldsymbol{v}_{b/c}$ مع a = m وb = b وc = w: $\boldsymbol{v}_{m/w} = \boldsymbol{v}_{m/b} + \boldsymbol{v}_{b/w}$.', '["الحد الثاني يجب أن يكون سرعة القارب بالنسبة إلى الماء $\\boldsymbol{v}_{b/w}$ لا العكس.","","$\\boldsymbol{v}_{b/m}$ سرعة القارب بالنسبة إلى الكرة، والمطلوب سرعة الكرة بالنسبة إلى القارب.","المعادلة جمع اتجاهي لا طرح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.293Z"}'::jsonb),
('mcq', 5, 0, 'إذا اقترب b من c بسرعة معينة فإن c يقترب من b بالمقدار نفسه في الاتجاه المعاكس؛ أي $\boldsymbol{v}_{c/b} = -\boldsymbol{v}_{b/c}$؛ فهما متساويتان مقدارًا ومتعاكستان اتجاهًا.', '["","إذا تحرك b نحو جهة بالنسبة إلى c فإن c يتحرك نحو الجهة المعاكسة بالنسبة إلى b.","السرعتان على خط واحد لا متعامدتان.","تبديل الإطار المرجعي لا يغيّر المقدار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.293Z"}'::jsonb),
('mcq', 6, 3, 'المعادلة $\boldsymbol{v}_{x/z} = \boldsymbol{v}_{x/y} + \boldsymbol{v}_{y/z}$؛ فالجسم الوسيط y يظهر ثانيًا في الحد الأول وأولًا في الحد الثاني.', '["هذه تعاكس السرعة المعلومة، ولا تربط y بالجسم z.","هذه سرعة z بالنسبة إلى y، وتعاكس $\\boldsymbol{v}_{y/z}$ المطلوبة في المعادلة.","هذه هي السرعة المجهولة نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.293Z"}'::jsonb),
('mcq', 7, 2, 'المعادلة جمع اتجاهي؛ فلا يساوي مقدار المحصلة مجموع المقدارين إلا إذا كان المتجهان في الاتجاه نفسه، ويساوي الفرق إذا تعاكسا، ويُحسب بفيثاغورس إذا تعامدا.', '["الجمع في المعادلة اتجاهي، فلا يساوي مجموع المقدارين إلا في حالة واحدة.","في حالة التعامد يُستعمل فيثاغورس، والناتج أقل من مجموع المقدارين.","","في حالة التعاكس يكون المقدار الفرق بين المقدارين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-21T13:36:33.294Z"}'::jsonb),
('essay', 1, null::int, null, null, '$\boldsymbol{v}_{a/c} = \boldsymbol{v}_{a/b} + \boldsymbol{v}_{b/c}$. $\boldsymbol{v}_{a/c}$: سرعة الجسم a بالنسبة إلى الجسم c. $\boldsymbol{v}_{a/b}$: سرعة الجسم a بالنسبة إلى الجسم b. $\boldsymbol{v}_{b/c}$: سرعة الجسم b بالنسبة إلى الجسم c. والرموز بخط عريض لأنها كميات متجهة. بالكلمات: سرعة الجسم a بالنسبة إلى الجسم c هي حاصل الجمع الاتجاهي لسرعة الجسم a بالنسبة إلى الجسم b، ثم سرعة الجسم b بالنسبة إلى الجسم c.', '["المعادلة صحيحة","دلالة الرموز الثلاثة","أنها كميات متجهة والجمع اتجاهي","التعبير بالكلمات"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"دلالة الرموز","marks":1},{"element":"الجمع الاتجاهي","marks":1},{"element":"الصياغة اللفظية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة صحيحة مع دلالة جميع الرموز والجمع الاتجاهي وصياغة لفظية"},{"level":"2–3 درجات","description":"معادلة صحيحة مع نقص في دلالة رمز أو في الصياغة"},{"level":"درجة واحدة","description":"معادلة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس ترتيب الحروف في أحد الحدود","عدّ الجمع جمعًا جبريًّا دائمًا","تفسير الخط المائل بأنه قسمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.294Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $\boldsymbol{v}_{m/b} = \boldsymbol{v}_{m/w} - \boldsymbol{v}_{b/w}$، ويمكن كتابتها $\boldsymbol{v}_{m/b} = \boldsymbol{v}_{m/w} + \boldsymbol{v}_{w/b}$. (ب) لأن تبديل الجسم المتحرك والإطار المرجعي يعطي السرعة نفسها مقدارًا في الاتجاه المعاكس: إذا تحرك القارب شرقًا بالنسبة إلى الماء فإن الماء يتحرك غربًا بالنسبة إلى القارب. (ج) $v_{m/b} = +4.3 - 3.5 = +0.8\ \text{m/s}$؛ أي تتحرك الكرة بالنسبة إلى القارب بسرعة 0.8 m/s نحو الشرق (نحو مقدمة القارب إذا كان القارب متجهًا شرقًا).', '["إعادة الترتيب صحيحة","تفسير العلاقة بين الرمزين المعكوسين","الحساب $+0.8\\ \\text{m/s}$","تفسير الإشارة والاتجاه"]'::jsonb, '["$\\boldsymbol{v}_{m/b} = \\boldsymbol{v}_{m/w} - \\boldsymbol{v}_{b/w}$","$v_{m/b} = (+4.3) - (+3.5) = +0.8\\ \\text{m/s}$","الإشارة الموجبة تعني نحو الشرق"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج) الحساب","marks":1},{"element":"(ج) التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة مع التفسير"},{"level":"2–3 درجات","description":"جزآن صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع $v_{m/w}$ و$v_{b/w}$ بدل الطرح","عدّ $\\boldsymbol{v}_{w/b}$ مساويًا لـ$\\boldsymbol{v}_{b/w}$","إهمال تفسير الإشارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.295Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المعادلة خاطئة؛ لأن $\boldsymbol{v}_{t/y}$ سرعة القطار بالنسبة إلى الراكب لا سرعة الراكب بالنسبة إلى القطار، ولأن الحروف لا تتسلسل (الجسم الوسيط يجب أن يكون آخر الحد الأول وأول الحد الثاني). الصحيحة: $\boldsymbol{v}_{y/E} = \boldsymbol{v}_{y/t} + \boldsymbol{v}_{t/E}$. بالمعادلة الصحيحة: $v_{y/E} = (+2.0) + (+15.0) = +17.0\ \text{m/s}$. بمعادلة الطالب: $v_{t/y} = -2.0\ \text{m/s}$ فتعطي $+15.0 + (-2.0) = +13.0\ \text{m/s}$. النتيجة المنطقية 17.0 m/s؛ لأن الراكب يمشي في اتجاه حركة القطار فيجب أن تكون سرعته بالنسبة إلى الأرض أكبر من سرعة القطار.', '["تحديد الخطأ في الرمز $\\boldsymbol{v}_{t/y}$","كتابة المعادلة الصحيحة","17.0 m/s بالمعادلة الصحيحة و13.0 m/s بمعادلة الطالب","الحكم على منطقية النتيجة"]'::jsonb, '["$v_{y/E} = v_{y/t} + v_{t/E} = (+2.0) + (+15.0) = +17.0\\ \\text{m/s}$","$v_{t/y} = -v_{y/t} = -2.0\\ \\text{m/s}$","معادلة الطالب: $(+15.0) + (-2.0) = +13.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"المعادلة الصحيحة","marks":1},{"element":"الحسابان","marks":1},{"element":"الحكم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ وتصحيحه وحسابان صحيحان وحكم معلّل"},{"level":"2–3 درجات","description":"تصحيح المعادلة مع خطأ في أحد الحسابين أو في الحكم"},{"level":"درجة واحدة","description":"تصحيح المعادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المعادلتين متكافئتين","التعويض بـ$+2.0$ عن $v_{t/y}$","إهمال الحكم على منطقية الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.295Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L3-O03') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تركب قطارًا يتحرك بسرعة 18.0 m/s بالنسبة إلى الأرض، وتركض داخله في اتجاه مقدمته بسرعة 2.5 m/s بالنسبة إلى القطار. ما مقدار سرعتك بالنسبة إلى الأرض؟', null, null, '["15.5 m/s","20.5 m/s","18.0 m/s","2.5 m/s"]'::jsonb, 'تطبيق', 'جمع سرعتين في الاتجاه نفسه', 'سهل', 'الكتاب ص 174 — المسألة 19'),
('mcq', 2, 'يمشي شخص على ممر متحرك بسرعة 1.5 m/s بالنسبة إلى الممر، عكس اتجاه حركة الممر الذي يتحرك بسرعة 1.2 m/s بالنسبة إلى الأرض، كما في الشكل الآتي. إذا كان اتجاه حركة الممر هو الاتجاه الموجب، فما سرعة الشخص المتجهة بالنسبة إلى الأرض؟', null, '[{"src":"qimg/phys1/c6l3-o04-walkway.svg","alt":"ممر متحرك مرسوم شريطًا أفقيًّا، وفوقه نقطة مكتوب فوقها الشخص. فوق الشخص سهم أحمر نحو اليسار مكتوب فوقه 1.5 m/s وتحته بالنسبة إلى الممر. تحت الممر سهم أحمر أقصر نحو اليمين مكتوب تحته 1.2 m/s وبجانبه الممر المتحرك بالنسبة إلى الأرض. في الأسفل سهم +x نحو اليمين."}]'::jsonb, '["$+0.3\\ \\text{m/s}$","$-2.7\\ \\text{m/s}$","$+2.7\\ \\text{m/s}$","$-0.3\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'طرح سرعتين متعاكستين مع الإشارة', 'متوسط', 'الكتاب ص 172 — الشكل 6-9b'),
('mcq', 3, 'يتحرك قارب بسرعة 3.2 m/s بالنسبة إلى ماء نهر، فيقيس راصد يقف على الضفة سرعة القارب 4.0 m/s في اتجاه حركته. ما سرعة ماء النهر؟', null, null, '["0.8 m/s في اتجاه حركة القارب","0.8 m/s عكس اتجاه حركة القارب","7.2 m/s في اتجاه حركة القارب","7.2 m/s عكس اتجاه حركة القارب"]'::jsonb, 'تحليل', 'استنتاج سرعة مجهولة في بعد واحد', 'متوسط', 'الكتاب ص 174 — المسألة 20'),
('mcq', 4, 'تتحرك السيارة A بسرعة 90 km/h نحو الشرق، والسيارة B بسرعة 80 km/h نحو الغرب على طريق مستقيم، كما في الشكل الآتي (السرعتان بالنسبة إلى الأرض). ما سرعة السيارة B المتجهة بالنسبة إلى السيارة A؟', null, '[{"src":"qimg/phys1/c6l3-o04-cars.svg","alt":"طريق أفقي ذو مسارين. في المسار السفلي السيارة A وأمامها سهم أحمر نحو اليمين مكتوب فوقه 90 km/h. في المسار العلوي السيارة B وأمامها سهم أحمر نحو اليسار أقصر قليلًا مكتوب فوقه 80 km/h. في أسفل اليمين سهم نحو اليمين مكتوب عنده الشرق."}]'::jsonb, '["10 km/h نحو الغرب","170 km/h نحو الشرق","170 km/h نحو الغرب","10 km/h نحو الشرق"]'::jsonb, 'تطبيق', 'سرعة نسبية لحركتين متعاكستين', 'متوسط', 'الكتاب ص 180 — السؤال 32'),
('mcq', 5, 'تسير سيارتك بسرعة 100 km/h، وأمامك سيارة أخرى تسير في الاتجاه نفسه بسرعة 85 km/h، كما في الشكل الآتي (السرعتان بالنسبة إلى الأرض، واتجاه الحركة موجب). ما سرعة السيارة الأخرى المتجهة بالنسبة إليك؟', null, '[{"src":"qimg/phys1/c6l3-o04-overtake.svg","alt":"طريق أفقي، عليه سيارتك في اليسار وأمامها سهم أحمر نحو اليمين مكتوب فوقه 100 km/h، وإلى يمينها السيارة الأخرى وأمامها سهم أحمر أقصر نحو اليمين مكتوب فوقه 85 km/h. في أسفل اليمين سهم +x نحو اليمين."}]'::jsonb, '["$+15\\ \\text{km/h}$","$-15\\ \\text{km/h}$","$-185\\ \\text{km/h}$","$+185\\ \\text{km/h}$"]'::jsonb, 'تطبيق', 'سرعة نسبية لحركتين في الاتجاه نفسه', 'سهل', 'الكتاب ص 181 — السؤال 37'),
('mcq', 6, 'أقصى سرعة لقارب صيد 4.5 m/s بالنسبة إلى ماء نهر يجري بسرعة 1.5 m/s. ما أدنى سرعة يتحرك بها القارب بالنسبة إلى الضفة عندما يسير بأقصى سرعته في خط موازٍ للضفة؟', null, null, '["6.0 m/s مع التيار","3.0 m/s مع التيار","1.5 m/s مع التيار","3.0 m/s ضد التيار"]'::jsonb, 'تحليل', 'مقارنة الجمع والطرح في بعد واحد', 'صعب', 'الكتاب ص 175 — السؤال 22'),
('mcq', 7, 'سفينة تتحرك بسرعة $+8.0\ \text{m/s}$ بالنسبة إلى الماء، ويقود بحار دراجة على سطحها بسرعة $-5.0\ \text{m/s}$ بالنسبة إلى السفينة (على خط حركة السفينة نفسه). ما سرعة البحار المتجهة بالنسبة إلى الماء؟', null, null, '["$+3.0\\ \\text{m/s}$","$-3.0\\ \\text{m/s}$","$+13\\ \\text{m/s}$","$-13\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'جمع سرعتين بإشارتيهما', 'صعب', 'الكتاب ص 172 — الجمع والطرح في خط مستقيم'),
('essay', 1, 'يركض طالب على ضفة نهر بسرعة 3.0 m/s نحو الشمال بالنسبة إلى الأرض، ويرى قاربًا يتحرك بسرعة 6.0 m/s بالنسبة إلى الضفة. احسب سرعة القارب بالنسبة إلى الطالب (مقدارًا واتجاهًا) في الحالتين:
(أ) القارب يتحرك نحو الجنوب مقتربًا منه.
(ب) القارب يتحرك نحو الشمال.', null, null, null, 'تطبيق', 'حساب سرعة نسبية في بعد واحد', 'سهل', 'الكتاب ص 183 — السؤال 5'),
('essay', 2, 'يتحرك قطار بسرعة 30.0 m/s نحو الشرق بالنسبة إلى الأرض. باتجاه الشرق موجبًا، احسب سرعة راكب بالنسبة إلى الأرض عندما:
(أ) يجلس في مقعده.
(ب) يمشي نحو مقدمة القطار بسرعة 1.5 m/s بالنسبة إلى القطار.
(ج) يمشي نحو مؤخرة القطار بسرعة 1.5 m/s بالنسبة إلى القطار.
ثم بيّن متى تُجمع السرعتان ومتى تُطرحان.', null, null, null, 'تطبيق', 'حساب سرعة نسبية في بعد واحد', 'متوسط', 'الكتاب ص 172، 174 — الشكل 6-9 والمسألة 19'),
('essay', 3, 'تسير سيارتك بسرعة 30.0 m/s على طريق سريع مستقيم، وتريد أن تتجاوز سيارة أخرى تسير بسرعة 25.0 m/s في الاتجاه نفسه (السرعتان بالنسبة إلى الأرض)، ويلزمك لإتمام التجاوز أن تتقدم 40.0 m بالنسبة إليها.
(أ) احسب سرعتك بالنسبة إلى السيارة الأخرى، والزمن اللازم للتجاوز.
(ب) احسب الزمن اللازم لتمر السيارتان إحداهما بالأخرى المسافة النسبية نفسها لو كانت الأخرى تسير بسرعة 25.0 m/s في الاتجاه المعاكس.
(ج) فسّر لماذا يستغرق التجاوز في الاتجاه نفسه زمنًا أطول.', null, null, null, 'تحليل', 'تحليل موقف بالسرعة النسبية', 'صعب', 'الكتاب ص 181 — السؤال 37')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L3-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الحركتان في الاتجاه نفسه فتُجمع السرعتان: $18.0 + 2.5 = 20.5\ \text{m/s}$ في اتجاه حركة القطار.', '["طُرحت السرعتان، وهما في الاتجاه نفسه فتُجمعان.","","هذه سرعة القطار وحدها؛ أُهملت سرعتك بالنسبة إلى القطار.","هذه سرعتك بالنسبة إلى القطار لا بالنسبة إلى الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.296Z"}'::jsonb),
('mcq', 2, 3, '$v = (-1.5) + (+1.2) = -0.3\ \text{m/s}$؛ أي يتحرك الشخص ببطء عكس اتجاه حركة الممر.', '["الفرق صحيح مقدارًا، لكن الإشارة خطأ؛ فسرعة الشخص أكبر من سرعة الممر وعكسها، فيتحرك في الاتجاه السالب.","جُمع المقداران كأن الحركتين في الاتجاه نفسه، وهما متعاكستان.","جُمع المقداران وأُخذ اتجاه الممر، والحركتان متعاكستان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.297Z"}'::jsonb),
('mcq', 3, 0, 'سرعة القارب بالنسبة إلى الضفة = سرعته بالنسبة إلى الماء + سرعة الماء بالنسبة إلى الضفة، فسرعة الماء $= 4.0 - 3.2 = 0.8\ \text{m/s}$، وموجبة فهي في اتجاه حركة القارب.', '["","لو جرى الماء عكس القارب لكانت سرعة القارب بالنسبة إلى الضفة أقل من 3.2 m/s لا أكبر.","جُمعت السرعتان، والمطلوب سرعة الماء، وهي الفرق بينهما.","جُمعت السرعتان وعُكس الاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.297Z"}'::jsonb),
('mcq', 4, 2, 'باتجاه الشرق موجبًا: $v_{B/A} = v_{B/E} - v_{A/E} = (-80) - (+90) = -170\ \text{km/h}$، أي 170 km/h نحو الغرب.', '["طُرح المقداران كأن السيارتين في الاتجاه نفسه، وهما متعاكستان.","المقدار صحيح، لكن B تقترب من A متجهةً نحو الغرب بالنسبة إليها.","","طُرح المقداران وعُكس الاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-21T13:36:33.298Z"}'::jsonb),
('mcq', 5, 1, 'سرعة السيارة الأخرى بالنسبة إليك = سرعتها بالنسبة إلى الأرض − سرعتك بالنسبة إلى الأرض $= 85 - 100 = -15\ \text{km/h}$؛ أي تبدو لك السيارة الأخرى متحركة نحوك بسرعة 15 km/h.', '["الفرق صحيح مقدارًا، لكن السيارة الأخرى أبطأ فتقترب منك عائدةً إليك، أي في الاتجاه السالب بالنسبة إليك.","","جُمع المقداران كأن السيارتين متعاكستان.","جُمع المقداران، والسيارتان في الاتجاه نفسه فيُطرحان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-21T13:36:33.298Z"}'::jsonb),
('mcq', 6, 3, 'عند السير عكس التيار تتعاكس السرعتان فتُطرحان: $4.5 - 1.5 = 3.0\ \text{m/s}$ عكس اتجاه التيار، وهي أدنى سرعة؛ وأقصاها مع التيار $4.5 + 1.5 = 6.0\ \text{m/s}$.', '["هذه أقصى سرعة (عند السير مع التيار)، والمطلوب الأدنى.","المقدار صحيح، لكن القارب في هذه الحالة يسير عكس التيار.","هذه سرعة التيار وحدها، أُهملت سرعة القارب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.298Z"}'::jsonb),
('mcq', 7, 0, '$v = (-5.0) + (+8.0) = +3.0\ \text{m/s}$؛ أي يتحرك البحار في اتجاه حركة السفينة بالنسبة إلى الماء لكن ببطء أكبر منها.', '["","طُرح المقداران ($8.0 - 5.0$) وأُعطيت النتيجة إشارة سرعة الدراجة؛ والمعادلة تجمع السرعتين بإشارتيهما، فتأخذ النتيجة إشارة السرعة الأكبر مقدارًا (سرعة السفينة).","جُمع المقداران متجاهلًا الإشارة السالبة لسرعة الدراجة.","جُمع المقداران وأُعطيت النتيجة إشارة الدراجة، مع أن السرعتين متعاكستان فيُطرح مقداراهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.299Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نختار الشمال موجبًا. سرعة القارب بالنسبة إلى الطالب = سرعة القارب بالنسبة إلى الأرض − سرعة الطالب بالنسبة إلى الأرض. (أ) $(-6.0) - (+3.0) = -9.0\ \text{m/s}$، أي 9.0 m/s نحو الجنوب؛ الحركتان متعاكستان فيُجمع المقداران. (ب) $(+6.0) - (+3.0) = +3.0\ \text{m/s}$، أي 3.0 m/s نحو الشمال؛ الحركتان في الاتجاه نفسه فيُطرح المقداران.', '["اختيار اتجاه موجب","الحالة (أ): 9.0 m/s جنوبًا","الحالة (ب): 3.0 m/s شمالًا","تعليل الجمع والطرح"]'::jsonb, '["الشمال موجب","(أ) $v = (-6.0) - (+3.0) = -9.0\\ \\text{m/s}$","(ب) $v = (+6.0) - (+3.0) = +3.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"اتجاه موجب","marks":1},{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحالتان صحيحتان مقدارًا واتجاهًا مع التعليل"},{"level":"2–3 درجات","description":"حالة واحدة صحيحة أو إهمال الاتجاه"},{"level":"درجة واحدة","description":"اختيار اتجاه موجب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح المقدارين في حالة التعاكس","إهمال ذكر الاتجاه","حساب سرعة الطالب بالنسبة إلى القارب بدل العكس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.300Z"}'::jsonb),
('essay', 2, null::int, null, null, '$v_{y/E} = v_{y/t} + v_{t/E}$. (أ) $0 + 30.0 = +30.0\ \text{m/s}$. (ب) $(+1.5) + (+30.0) = +31.5\ \text{m/s}$. (ج) $(-1.5) + (+30.0) = +28.5\ \text{m/s}$. تُجمع المقادير عندما تكون الحركتان في الاتجاه نفسه، ويُطرح أصغرهما من أكبرهما عندما تكونان متعاكستين، وتأخذ النتيجة اتجاه الأكبر.', '["(أ) +30.0 m/s","(ب) +31.5 m/s","(ج) +28.5 m/s","قاعدة الجمع والطرح"]'::jsonb, '["(أ) $0 + 30.0 = +30.0\\ \\text{m/s}$","(ب) $(+1.5) + (+30.0) = +31.5\\ \\text{m/s}$","(ج) $(-1.5) + (+30.0) = +28.5\\ \\text{m/s}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"القاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات الثلاثة صحيحة مع القاعدة"},{"level":"2–3 درجات","description":"حسابان صحيحان"},{"level":"درجة واحدة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ سرعة الراكب الجالس صفرًا بالنسبة إلى الأرض","جمع 1.5 في الحالة (ج)","إهمال الإشارات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.300Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحركتان في الاتجاه نفسه: $30.0 - 25.0 = 5.0\ \text{m/s}$، والزمن $\frac{40.0}{5.0} = 8.0\ \text{s}$. (ب) الحركتان متعاكستان: $30.0 + 25.0 = 55.0\ \text{m/s}$، والزمن $\frac{40.0}{55.0} = 0.727\ \text{s}$. (ج) الزمن يعتمد على السرعة النسبية بين السيارتين؛ وهي صغيرة عندما تتحركان في الاتجاه نفسه (تُطرح السرعتان) وكبيرة عندما تتعاكسان (تُجمعان)، فيطول زمن التجاوز في الحالة الأولى.', '["السرعة النسبية 5.0 m/s والزمن 8.0 s","السرعة النسبية 55.0 m/s والزمن 0.727 s","ربط الزمن بالسرعة النسبية","تفسير الجمع والطرح"]'::jsonb, '["$v = 30.0 - 25.0 = 5.0\\ \\text{m/s}$، $t = \\frac{40.0}{5.0} = 8.0\\ \\text{s}$","$v = 30.0 + 25.0 = 55.0\\ \\text{m/s}$، $t = \\frac{40.0}{55.0} = 0.727\\ \\text{s}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج) الربط بالسرعة النسبية","marks":1},{"element":"(ج) التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان مع تفسير قائم على السرعة النسبية"},{"level":"2–3 درجات","description":"حساب واحد صحيح مع تفسير مقبول"},{"level":"درجة واحدة","description":"تفسير صحيح دون حسابات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 40.0 m على 30.0 m/s","جمع السرعتين في الحالة الأولى","تفسير الاختلاف بسرعة سيارتك وحدها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.301Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L3-O04') and x.type = v.type and x.number = v.number
