insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L3-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تقود قاربًا لعبور نهر يجري ماؤه بسرعة كبيرة، وتريد الوصول إلى الرصيف المقابل تمامًا لنقطة انطلاقك. كيف توجّه القارب؟', null, null, '["بزاوية عكس التيار بحيث تلغي مركبة سرعته الموازية للضفة سرعةَ التيار","عموديًّا على الضفة تمامًا لأن التيار لا يؤثر في مسار القارب بالنسبة إلى الضفة","بزاوية مع اتجاه التيار لتزداد سرعة القارب بالنسبة إلى الضفة فيصل أسرع","موازيًا للضفة عكس التيار حتى يتوقف انجرافه ثم يعبر عموديًّا على الضفة"]'::jsonb, 'فهم', 'تحليل حركة في إطار مرجعي متحرك', 'سهل', 'الكتاب ص 175 — السؤال 26'),
('mcq', 2, 'يبيّن الشكل الآتي، على شبكة يمثل طول ضلع كل مربع فيها 1.0 m/s، سرعة قارب بالنسبة إلى الماء $\boldsymbol{v}_{b/w}$ وسرعة الماء بالنسبة إلى الضفة $\boldsymbol{v}_{w/E}$. ما سرعة القارب المتجهة بالنسبة إلى الضفة؟', null, '[{"src":"qimg/phys1/c6l3-o05-grid.svg","alt":"شبكة مربعات ومحوران: الشرق إلى اليمين والشمال إلى أعلى، ونقطة سوداء عند الأصل. سهم أحمر v b/w من الأصل إلى النقطة التي تبعد مربعين يسارًا وأربعة مربعات إلى أعلى، ومن رأسه سهم أحمر أفقي v w/E طوله مربعان نحو اليمين ينتهي على المحور الرأسي على ارتفاع أربعة مربعات. في أسفل اليسار سهم رمادي نحو اليمين مكتوب عنده اتجاه التيار. لا يظهر المتجه المحصل."}]'::jsonb, '["4.5 m/s بزاوية $27^\\circ$ غرب الشمال","5.7 m/s بزاوية $45^\\circ$ غرب الشمال","6.5 m/s نحو الشمال تمامًا","4.0 m/s نحو الشمال تمامًا"]'::jsonb, 'تحليل', 'تحليل مثلث سرعات على شبكة', 'متوسط', 'الكتاب ص 175، 182 — السؤالان 26 و47'),
('mcq', 3, 'تهاجر طيور الخرشنة مسافات طويلة. ماذا يحدث لطائر يحافظ على اتجاه طيرانه وسرعته بالنسبة إلى الهواء إذا هبّت رياح قوية في اتجاه عمودي على اتجاه حركته؟', null, null, '["تزداد سرعته بالنسبة إلى الأرض مقدارًا دون أن يتغير اتجاهها","ينحرف تدريجيًّا عن مساره فيتغير اتجاه سرعته بالنسبة إلى الأرض","تقل سرعته بالنسبة إلى الأرض مقدارًا دون أن يتغير اتجاهها","لا تتأثر سرعته بالنسبة إلى الأرض مطلقًا لأن الرياح عمودية عليه"]'::jsonb, 'فهم', 'تفسير أثر الرياح في الحركة', 'سهل', 'الكتاب ص 174 — الربط مع الأحياء'),
('mcq', 4, 'تطير طائرة بسرعة 220 km/h بالنسبة إلى الهواء من مدينة إلى أخرى تبعد 660 km ثم تعود، وتهب رياح ثابتة بسرعة 30 km/h في اتجاه الخط الواصل بين المدينتين. ما الذي يصح قوله في زمن الرحلة كاملة ذهابًا وإيابًا مقارنة بزمنها دون رياح؟', null, null, '["أقصر من زمنها دون رياح","مساوٍ لزمنها دون رياح لأن أثر الرياح يُلغى","أطول من زمنها دون رياح","لا يمكن الحكم دون معرفة اتجاه الرياح"]'::jsonb, 'تحليل', 'تحليل أثر الإطار المتحرك في زمن الحركة', 'صعب', 'الكتاب ص 173 — الملاحون الجويون'),
('mcq', 5, 'يجدف رجل بقاربه عكس التيار بسرعة 3.0 m/s بالنسبة إلى الماء، في نهر يجري بسرعة 1.0 m/s بالنسبة إلى الضفة، وبجانبه جذع شجرة يطفو مع التيار. ما سرعة القارب المتجهة بالنسبة إلى الجذع؟', null, null, '["2.0 m/s عكس التيار","3.0 m/s عكس التيار","1.0 m/s مع التيار","4.0 m/s عكس التيار"]'::jsonb, 'تحليل', 'تحليل الحركة في إطار مرجعي متحرك', 'متوسط', 'الكتاب ص 172–173 — مجموعة المحاور المتحركة'),
('mcq', 6, 'يبيّن الشكل الآتي سرعة الرياح بالنسبة إلى الأرض نحو الشمال، ومسارًا مطلوبًا من المطار إلى الوجهة نحو الشرق. في أيّ اتجاه يجب أن يوجّه الطيار مقدمة الطائرة لتتحرك على المسار المطلوب؟', null, '[{"src":"qimg/phys1/c6l3-o05-heading.svg","alt":"خط أفقي متقطع من نقطة على اليسار مكتوب تحتها المطار إلى نقطة على اليمين مكتوب فوقها الوجهة، ومكتوب تحت الخط المسار المطلوب. فوق الخط سهم أحمر رأسي إلى أعلى مكتوب بجانبه v الهواء بالنسبة إلى الأرض. في أعلى اليسار سهما الشمال (أعلى) والشرق (يمين)."}]'::jsonb, '["نحو الشرق تمامًا","نحو الجنوب تمامًا","في اتجاه يميل شمال الشرق","في اتجاه يميل جنوب الشرق"]'::jsonb, 'تحليل', 'تحليل اتجاه التوجيه في رياح جانبية', 'سهل', 'الكتاب ص 173 — الملاحون الجويون والشكل 6-10'),
('mcq', 7, 'يريد سبّاح عبور نهر يجري ماؤه بسرعة ثابتة في أقصر زمن ممكن، دون اهتمام بمكان وصوله على الضفة المقابلة. كيف يوجّه حركته بالنسبة إلى الماء؟', null, null, '["عموديًّا على الضفة، لتكون مركبة سرعته العمودية أكبر ما يمكن","بزاوية عكس التيار، ليصل إلى النقطة المقابلة لنقطة انطلاقه مباشرة","بزاوية مع التيار، لأن سرعته بالنسبة إلى الضفة تكون عندئذٍ أكبر","لا يتغير زمن العبور بتغيّر الاتجاه الذي يوجّه إليه السبّاح حركته"]'::jsonb, 'تحليل', 'تحليل الحركة في إطار متحرك (زمن العبور)', 'صعب', 'الكتاب ص 175، 182 — السؤالان 26 و46'),
('essay', 1, 'يوجّه ملاح مقدمة قاربه في اتجاه يصنع $30^\circ$ غرب الشمال، فيتحرك القارب نحو الشمال تمامًا بسرعة 5.0 m/s بالنسبة إلى الضفة، كما في الشكل الآتي، والتيار يجري نحو الشرق. حلّل الموقف برسم مثلث السرعات، ثم احسب سرعة التيار وسرعة القارب بالنسبة إلى الماء.', null, '[{"src":"qimg/phys1/c6l3-o05-e1.svg","alt":"نهر بين ضفتين، ومن نقطة سوداء عند الضفة السفلى سهم أحمر رأسي إلى أعلى مكتوب بجانبه v b/E و5.0 m/s، وخط متقطع يميل إلى أعلى اليسار مكتوب عند طرفه اتجاه مقدمة القارب، وبين الخط المتقطع والسهم الرأسي قوس زاوية مكتوب عنده 30 درجة. في يمين الشكل سهما الشمال والشرق، وفي أسفله سهم رمادي نحو اليمين مكتوب عنده اتجاه التيار. لا يظهر سهم التيار ولا سهم سرعة القارب بالنسبة إلى الماء."}]'::jsonb, null, 'تحليل', 'تحليل قارب في نهر جارٍ', 'متوسط', 'الكتاب ص 182 — السؤال 47'),
('essay', 2, 'طائرة سرعتها $2.00\times10^{2}\ \text{km/h}$ بالنسبة إلى الهواء، تريد الوصول إلى مدينة تقع على بعد $6.00\times10^{2}\ \text{km}$ شرقًا، وتهب رياح سرعتها 50.0 km/h بالنسبة إلى الأرض. حلّل الحالات الآتية واحسب زمن الرحلة في كل منها، ثم رتّبها من الأقصر زمنًا إلى الأطول:
(أ) الرياح نحو الشرق.
(ب) الرياح نحو الغرب.
(ج) الرياح نحو الشمال، ويوجّه الطيار الطائرة بحيث تسير شرقًا تمامًا (حدّد اتجاه مقدمتها).', null, null, null, 'تحليل', 'تحليل حركة طائرة في رياح مختلفة الاتجاه', 'صعب', 'الكتاب ص 173–175 — الملاحون الجويون والأسئلة 21 و24–25'),
('essay', 3, 'يعبر قارب نهرًا عرضه 69 m يجري ماؤه بسرعة 2.0 m/s، وسرعة القارب بالنسبة إلى الماء 5.0 m/s. قارن بين خطتين:
(أ) توجيه القارب عموديًّا على الضفة: احسب زمن العبور ومقدار انجرافه مع التيار.
(ب) توجيه القارب بزاوية عكس التيار ليصل إلى النقطة المقابلة تمامًا: احسب الزاوية مع العمودي على الضفة وزمن العبور.
ثم حدّد الخطة الأنسب لكل هدف.', null, null, null, 'تحليل', 'مقارنة خطتين لعبور نهر جارٍ', 'متوسط', 'الكتاب ص 175، 182 — السؤالان 26 و46')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
