from (values
('mcq', 1, 0, 'سرعة القارب بالنسبة إلى الضفة = سرعته بالنسبة إلى الماء + سرعة الماء بالنسبة إلى الضفة. ليكون المجموع عموديًّا على الضفة يجب أن تكون لسرعة القارب بالنسبة إلى الماء مركبة موازية للضفة عكس التيار تساويه مقدارًا، ومركبة عمودية تعبر بها النهر.', '["","التيار يحرك الماء والقارب معه، فينجرف القارب إذا وُجّه عموديًّا.","التوجيه مع التيار يزيد الانجراف بعيدًا عن الرصيف المقابل.","عند العبور العمودي بعد ذلك سينجرف القارب مع التيار من جديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.302Z"}'::jsonb),
('mcq', 2, 3, '$\boldsymbol{v}_{b/E} = \boldsymbol{v}_{b/w} + \boldsymbol{v}_{w/E}$. من الشبكة: $\boldsymbol{v}_{b/w}$ مركبتاه 2.0 m/s غربًا و4.0 m/s شمالًا، و$\boldsymbol{v}_{w/E}$ = 2.0 m/s شرقًا؛ فالمركبة الأفقية للمحصلة صفر، والمحصلة 4.0 m/s نحو الشمال تمامًا: القارب موجّه عكس التيار فيعبر عموديًّا على الضفة.', '["هذه سرعة القارب بالنسبة إلى الماء؛ أُهمل أثر التيار.","طُرحت سرعة التيار بدل جمعها، فصارت المركبة الأفقية 4.0 m/s نحو الغرب.","جُمع المقداران $4.5 + 2.0$ جمعًا جبريًّا، والمتجهان غير متوازيين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.302Z"}'::jsonb),
('mcq', 3, 1, 'سرعة الطائر بالنسبة إلى الأرض = سرعته بالنسبة إلى الهواء + سرعة الهواء بالنسبة إلى الأرض؛ والرياح العمودية تضيف مركبة جانبية، فتميل المحصلة عن اتجاه طيرانه وينحرف عن مساره تدريجيًّا.', '["الرياح العمودية تضيف مركبة جانبية فتغيّر الاتجاه أيضًا.","","الرياح العمودية لا تعاكس حركته، ولا تقلل سرعته بالنسبة إلى الأرض.","سرعة الهواء بالنسبة إلى الأرض تُجمع اتجاهيًّا مع سرعته فتغيّر المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-21T13:36:33.303Z"}'::jsonb),
('mcq', 4, 2, 'دون رياح: $\frac{2 \times 660}{220} = 6.00\ \text{h}$. مع الرياح: $\frac{660}{250} + \frac{660}{190} = 2.64 + 3.47 = 6.11\ \text{h}$؛ فالزمن أطول، لأن الطائرة تقضي في مواجهة الرياح زمنًا أطول مما تقضيه وهي تسير معها.', '["الزمن الذي تخسره الطائرة عند مواجهة الرياح أكبر من الزمن الذي تكسبه عند السير معها.","السرعتان تتعوضان، لكن الأزمنة لا تتعوض لأن الطائرة تقضي زمنًا أطول في مواجهة الرياح.","","النتيجة واحدة أيًّا كان اتجاه الرياح على امتداد المسار؛ فأحد الشوطين معها والآخر ضدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.303Z"}'::jsonb),
('mcq', 5, 1, 'الجذع يتحرك مع الماء فسرعته بالنسبة إلى الماء صفر، أي إن إطاره المرجعي هو إطار الماء. فسرعة القارب بالنسبة إلى الجذع = سرعته بالنسبة إلى الماء + صفر = 3.0 m/s عكس التيار.', '["هذه سرعة القارب بالنسبة إلى الضفة لا بالنسبة إلى الجذع.","","هذه سرعة الجذع (والماء) بالنسبة إلى الضفة.","جُمعت سرعة التيار مع سرعة القارب بالنسبة إلى الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.304Z"}'::jsonb),
('mcq', 6, 3, 'سرعة الطائرة بالنسبة إلى الأرض = سرعتها بالنسبة إلى الهواء + سرعة الرياح. لتكون المحصلة نحو الشرق يجب أن تكون لسرعة الطائرة بالنسبة إلى الهواء مركبة نحو الجنوب تلغي سرعة الرياح، ومركبة نحو الشرق؛ أي توجَّه المقدمة جنوب الشرق.', '["عندئذٍ تضيف الرياح مركبة نحو الشمال فتنحرف الطائرة شمال المسار.","لن يكون للطائرة عندئذٍ أي مركبة نحو الشرق، فلا تتقدم نحو الوجهة.","هذا يزيد الانحراف نحو الشمال بدل أن يلغيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.304Z"}'::jsonb),
('mcq', 7, 0, 'زمن العبور = عرض النهر ÷ مركبة السرعة العمودية على الضفة. التيار موازٍ للضفة فلا يغيّر هذه المركبة؛ وهي أكبر ما يمكن عندما يوجّه السباح حركته عموديًّا على الضفة.', '["","هذا التوجيه يقلل المركبة العمودية على الضفة فيطول زمن العبور.","المركبة الموازية للضفة لا تساعد على العبور؛ والمركبة العمودية تقل.","زمن العبور يعتمد على المركبة العمودية على الضفة، وهي تتغير بتغير الاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.305Z"}'::jsonb),
('essay', 1, null::int, null, null, '$\boldsymbol{v}_{b/E} = \boldsymbol{v}_{b/w} + \boldsymbol{v}_{w/E}$. المحصلة $\boldsymbol{v}_{b/E}$ = 5.0 m/s شمالًا، و$\boldsymbol{v}_{b/w}$ في اتجاه المقدمة ($30^\circ$ غرب الشمال)، و$\boldsymbol{v}_{w/E}$ أفقية نحو الشرق. في المثلث القائم: $\boldsymbol{v}_{b/w}$ هو الوتر، و$\boldsymbol{v}_{b/E}$ الضلع المجاور للزاوية $30^\circ$، والتيار الضلع المقابل. سرعة التيار $v_{w/E} = 5.0\tan 30^\circ = 2.9\ \text{m/s}$. سرعة القارب بالنسبة إلى الماء $v_{b/w} = \frac{5.0}{\cos 30^\circ} = 5.8\ \text{m/s}$. المركبة الغربية لسرعة القارب بالنسبة إلى الماء تلغي التيار فيتحرك شمالًا تمامًا.', '["المعادلة ورسم المثلث بتحديد الوتر","سرعة التيار 2.9 m/s شرقًا","سرعة القارب بالنسبة إلى الماء 5.8 m/s","تفسير إلغاء المركبة الغربية للتيار"]'::jsonb, '["$v_{w/E} = v_{b/E}\\tan 30^\\circ = 5.0 \\times 0.577 = 2.9\\ \\text{m/s}$","$v_{b/w} = \\frac{v_{b/E}}{\\cos 30^\\circ} = \\frac{5.0}{0.866} = 5.8\\ \\text{m/s}$"]'::jsonb, '[{"element":"المثلث","marks":1},{"element":"سرعة التيار","marks":1},{"element":"سرعة القارب بالنسبة إلى الماء","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مثلث صحيح وحسابان صحيحان مع التفسير"},{"level":"2–3 درجات","description":"مثلث صحيح وحساب واحد صحيح"},{"level":"درجة واحدة","description":"مثلث صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ 5.0 m/s سرعة القارب بالنسبة إلى الماء","استعمال $\\sin$ بدل $\\tan$ لسرعة التيار","رسم التيار نحو الغرب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.306Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السرعتان في الاتجاه نفسه: $200 + 50.0 = 250\ \text{km/h}$، والزمن $\frac{6.00\times10^{2}}{250} = 2.40\ \text{h}$. (ب) متعاكستان: $200 - 50.0 = 150\ \text{km/h}$، والزمن $\frac{6.00\times10^{2}}{150} = 4.00\ \text{h}$. (ج) يجب توجيه المقدمة جنوب الشرق بزاوية $\sin^{-1}\left(\frac{50.0}{200}\right) = 14.5^\circ$ لتلغي المركبة الجنوبية سرعة الرياح؛ سرعة الطائرة بالنسبة إلى الهواء هي الوتر، فسرعتها بالنسبة إلى الأرض $\sqrt{(200)^2 - (50.0)^2} = 194\ \text{km/h}$ شرقًا، والزمن $\frac{6.00\times10^{2}}{193.6} = 3.10\ \text{h}$. الترتيب: (أ) ثم (ج) ثم (ب).', '["(أ) 250 km/h و2.40 h","(ب) 150 km/h و4.00 h","(ج) التوجيه $14.5^\\circ$ جنوب الشرق و194 km/h و3.10 h","الترتيب الصحيح"]'::jsonb, '["(أ) $t = \\frac{6.00\\times10^{2}}{250} = 2.40\\ \\text{h}$","(ب) $t = \\frac{6.00\\times10^{2}}{150} = 4.00\\ \\text{h}$","(ج) $\\theta = \\sin^{-1}(50.0/200) = 14.5^\\circ$ جنوب الشرق","(ج) $v = \\sqrt{200^2 - 50.0^2} = 193.6 \\approx 194\\ \\text{km/h}$، $t = \\frac{6.00\\times10^{2}}{193.6} = 3.10\\ \\text{h}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2},{"element":"الترتيب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحالات الثلاث صحيحة مع التوجيه والترتيب"},{"level":"3–4 درجات","description":"حالتان صحيحتان أو خطأ في الحالة (ج) فقط"},{"level":"1–2 درجة","description":"حالة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع المربعين في الحالة (ج) فيعطي 206 km/h","توجيه الطائرة شمال الشرق في الحالة (ج)","عدّ الحالة (ج) دون أثر في الزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.306Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) مركبة السرعة العمودية على الضفة 5.0 m/s، فالزمن $\frac{69}{5.0} = 13.8\ \text{s} \approx 14\ \text{s}$، والانجراف $2.0 \times 13.8 = 28\ \text{m}$ في اتجاه التيار. (ب) لإلغاء التيار يجب أن تكون المركبة الموازية للضفة 2.0 m/s عكس التيار: $\sin\theta = \frac{2.0}{5.0}$ فـ$\theta = 24^\circ$ عكس التيار عن العمودي؛ والمركبة العمودية $\sqrt{(5.0)^2 - (2.0)^2} = 4.6\ \text{m/s}$، فالزمن $\frac{69}{4.58} = 15\ \text{s}$. الخطة (أ) أنسب لأقصر زمن عبور، والخطة (ب) أنسب للوصول إلى النقطة المقابلة دون انجراف.', '["(أ) الزمن 14 s والانجراف 28 m","(ب) الزاوية $24^\\circ$ عكس التيار","(ب) المركبة العمودية 4.6 m/s والزمن 15 s","المقارنة والحكم"]'::jsonb, '["(أ) $t = \\frac{69}{5.0} = 13.8\\ \\text{s}$، الانجراف $= 2.0 \\times 13.8 = 28\\ \\text{m}$","(ب) $\\theta = \\sin^{-1}(2.0/5.0) = 24^\\circ$","(ب) $v_\\perp = \\sqrt{5.0^2 - 2.0^2} = 4.6\\ \\text{m/s}$، $t = \\frac{69}{4.6} = 15\\ \\text{s}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"الزاوية","marks":1},{"element":"زمن (ب)","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات صحيحة مع مقارنة سليمة"},{"level":"2–3 درجات","description":"خطأ في أحد الحسابات مع مقارنة سليمة"},{"level":"درجة واحدة","description":"مقارنة صحيحة نوعيًّا دون حسابات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\tan$ بدل $\\sin$ لحساب الزاوية","قسمة العرض على 5.0 m/s في الخطة (ب)","قسمة العرض على سرعة القارب بالنسبة إلى الضفة في الخطة (أ)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.307Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
